insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('energy-budget-week-planner', 'Energy Budget Week Planner', 'worksheet'::resource_kind, 'A one-page planner where a client lists the week''s demands and decides where limited energy will go.', 'Use it to help a client plan around energy instead of guilt.', array['Adults']::text[], '30 minutes', 'Have the client list every standing demand for the week, rate how much energy each costs, and mark two that can shrink or wait. Watch for clients who budget zero for rest; ask what a good-enough week looks like. The plan is theirs to revise at the next session.', '[{"id": "f0", "type": "textarea", "label": "Demands I already have this week"}, {"id": "f1", "type": "textarea", "label": "Which ones drain me most, and why"}, {"id": "f2", "type": "textarea", "label": "Two I can shrink, share or postpone"}, {"id": "f3", "type": "textarea", "label": "Where I will protect time to recover"}, {"id": "f4", "type": "textarea", "label": "What I will tell someone about my plan"}]'::jsonb, array['planning', 'routines', 'pacing']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('hard-talk-preparation-page', 'Hard Talk Preparation Page', 'worksheet'::resource_kind, 'A planning page for sorting what a client wants to say, ask for and leave unsaid before a hard conversation.', 'Use it to help a client enter a hard talk with a clear aim.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through the page in session before the real conversation. Ask the client to name one outcome that is within their control, since many aim for the other person''s reaction. Rehearse the first two sentences aloud. Revisit afterward to talk about what went as hoped and what did not.', '[{"id": "f0", "type": "textarea", "label": "Who I need to talk to and about what"}, {"id": "f1", "type": "textarea", "label": "What I most want them to understand"}, {"id": "f2", "type": "textarea", "label": "One thing I am asking for"}, {"id": "f3", "type": "textarea", "label": "What I will not bring up this time"}, {"id": "f4", "type": "textarea", "label": "My first two sentences"}, {"id": "f5", "type": "textarea", "label": "How I will take care of myself afterward"}]'::jsonb, array['communication', 'planning', 'boundaries']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('last-hour-before-bed-routine-builder', 'Last Hour Before Bed Routine Builder', 'worksheet'::resource_kind, 'A worksheet for designing a short, realistic routine for the last hour before bed.', 'Use it to help a client build a calm, repeatable evening routine.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to describe a typical evening first, then choose three small steps they would actually do on a tired night. Keep the routine short enough to survive a bad day. Invite them to track for a week and bring the page back to adjust it together.', '[{"id": "f0", "type": "textarea", "label": "What my evenings look like now"}, {"id": "f1", "type": "textarea", "label": "Screens or tasks I want to stop earlier"}, {"id": "f2", "type": "textarea", "label": "Three small steps I could do each night"}, {"id": "f3", "type": "textarea", "label": "What cue will remind me to start"}, {"id": "f4", "type": "textarea", "label": "What I will do if I fall off the routine"}]'::jsonb, array['routines', 'sleep', 'self-monitoring']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('strengths-in-hindsight-page', 'Strengths in Hindsight Page', 'worksheet'::resource_kind, 'A reflective page where a client looks back on a hard stretch and names the strengths they used to get through.', 'Use it to help a client notice strengths already in use.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a past difficulty the client has already come through, not a current crisis. Help them move from what went wrong to what they did anyway. Some clients dismiss this as luck; ask what a friend would say they did. Keep the focus on actions, not outcomes.', '[{"id": "f0", "type": "textarea", "label": "A hard stretch I came through"}, {"id": "f1", "type": "textarea", "label": "What I did, even in small ways"}, {"id": "f2", "type": "textarea", "label": "A strength that shows in what I did"}, {"id": "f3", "type": "textarea", "label": "Who or what helped me"}, {"id": "f4", "type": "textarea", "label": "Where I could use this strength now"}]'::jsonb, array['strengths', 'self-esteem', 'reflection']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('choice-weighing-grid-with-values-column', 'Choice Weighing Grid with Values Column', 'worksheet'::resource_kind, 'A grid that sets the pros and cons of a choice beside the values each option serves or costs.', 'Use it to help a client weigh a choice by what matters to them.', array['Adults']::text[], '30 minutes', 'Fill the grid in session for one real decision. The values column keeps clients from tallying pros and cons as if the longer list wins. Notice when they list what others expect; ask which entries are their own. It is a way to think aloud together, not a way to pick for them.', '[{"id": "f0", "type": "textarea", "label": "The decision I am facing"}, {"id": "f1", "type": "textarea", "label": "Pros of each option"}, {"id": "f2", "type": "textarea", "label": "Cons of each option"}, {"id": "f3", "type": "textarea", "label": "Values each option serves"}, {"id": "f4", "type": "textarea", "label": "Values each option costs"}, {"id": "f5", "type": "textarea", "label": "One small step that would give me more information"}]'::jsonb, array['decision making', 'values', 'planning']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('key-thought-circler', 'Key Thought Circler', 'cbt'::resource_kind, 'A thought record variation where a client circles the one thought in a situation that carries the most feeling.', 'Use it to help a client focus a thought record on the key thought.', array['Adults', 'Teens']::text[], '20 minutes', 'Many clients produce a long list of thoughts and then stall. Have them circle the one that brings the strongest feeling, then examine only that one for evidence for and against. Ask what the thought predicts and whether that has happened. Keep the balanced thought in their words.', '[{"id": "f0", "type": "textarea", "label": "The situation, in one sentence"}, {"id": "f1", "type": "textarea", "label": "Thoughts that went through my mind"}, {"id": "f2", "type": "textarea", "label": "The thought that carries the most feeling"}, {"id": "f3", "type": "textarea", "label": "Evidence that supports it"}, {"id": "f4", "type": "textarea", "label": "Evidence that does not fit it"}, {"id": "f5", "type": "textarea", "label": "A more balanced thought I could try"}, {"id": "f6", "type": "textarea", "label": "How strong the feeling is now"}]'::jsonb, array['thinking traps', 'automatic thoughts', 'core CBT']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('probability-and-cost-estimator', 'Probability and Cost Estimator', 'cbt'::resource_kind, 'A page where a client estimates how likely a feared outcome is and how they would cope if it happened.', 'Use it to separate how likely a worry is from how bearable it would be.', array['Adults']::text[], '25 minutes', 'Ask for the feared outcome in one sentence, then a gut estimate of how likely it is, then a calmer second estimate after listing what has happened before in similar situations. The coping column matters as much as the odds. Do not argue the number; let the client move it.', '[{"id": "f0", "type": "textarea", "label": "The outcome I am afraid of"}, {"id": "f1", "type": "textarea", "label": "How likely it feels, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What has actually happened in similar situations"}, {"id": "f3", "type": "textarea", "label": "If it did happen, what would I do first"}, {"id": "f4", "type": "textarea", "label": "Who could help me"}, {"id": "f5", "type": "textarea", "label": "How likely it feels after looking at this"}]'::jsonb, array['worry', 'uncertainty', 'thinking traps']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('prediction-test-planner', 'Prediction Test Planner', 'cbt'::resource_kind, 'A planner for testing a prediction in real life, with the prediction, the test and what actually happened.', 'Use it to help a client test a belief by trying something small.', array['Adults', 'Teens']::text[], 'Full session', 'Pick one prediction that can be tested in a week, such as what happens if the client asks a question in a meeting. Write the prediction with a rating first. Plan a safe, specific test. At the next session compare what happened with what was predicted, without declaring a winner.', '[{"id": "f0", "type": "textarea", "label": "The belief I want to test"}, {"id": "f1", "type": "textarea", "label": "My prediction, and how sure I am"}, {"id": "f2", "type": "textarea", "label": "The small test I will run"}, {"id": "f3", "type": "textarea", "label": "What I will watch for"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "What I learned, and how sure I am now"}]'::jsonb, array['behavioral experiment', 'core CBT', 'avoidance']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('problem-size-and-solution-ladder', 'Problem Size and Solution Ladder', 'cbt'::resource_kind, 'A ladder for breaking one overwhelming problem into smaller rungs, each with a first action.', 'Use it to turn an overwhelming problem into a short list of next steps.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client name the problem, then split it into parts and order the parts from easiest to hardest. Choose only the bottom rung for this week. Clients often want to solve the top rung first; gently ask what would make the first step doable. Review progress next time.', '[{"id": "f0", "type": "textarea", "label": "The problem, in plain words"}, {"id": "f1", "type": "textarea", "label": "The parts it is made of"}, {"id": "f2", "type": "textarea", "label": "The easiest part to start with"}, {"id": "f3", "type": "textarea", "label": "A first action I can take this week"}, {"id": "f4", "type": "textarea", "label": "What might get in the way"}, {"id": "f5", "type": "textarea", "label": "How I will know I took the step"}]'::jsonb, array['planning', 'problem solving', 'core CBT']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('thought-courtroom-role-play-sheet', 'Thought Courtroom Role Play Sheet', 'cbt'::resource_kind, 'A sheet where a client plays defense, prosecution and judge for one critical thought about themselves.', 'Use it to help a client weigh a harsh thought from several angles.', array['Adults', 'Teens']::text[], '25 minutes', 'Set up the three roles and let the client write each voice in turn, with you reading the other parts if helpful. The judge''s verdict should be a statement they could say to a friend. Some clients get stuck defending the thought; ask what a fair judge would not allow into evidence.', '[{"id": "f0", "type": "textarea", "label": "The thought on trial"}, {"id": "f1", "type": "textarea", "label": "The prosecution: why it might be true"}, {"id": "f2", "type": "textarea", "label": "The defense: why it might not be"}, {"id": "f3", "type": "textarea", "label": "Facts the judge would accept"}, {"id": "f4", "type": "textarea", "label": "The judge''s balanced verdict"}, {"id": "f5", "type": "textarea", "label": "How I feel about the thought now"}]'::jsonb, array['thinking traps', 'self-criticism', 'automatic thoughts']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('passengers-on-the-bus-metaphor-page', 'Passengers on the Bus Metaphor Page', 'act'::resource_kind, 'A page built on the passengers-on-the-bus metaphor, naming unwelcome thoughts as passengers while the client drives.', 'Use it to help a client keep driving toward a value with noisy passengers aboard.', array['Adults', 'Teens']::text[], '25 minutes', 'Introduce the metaphor aloud, then let the client name their loudest passengers and where they want the bus to go. The point is not to throw anyone off but to keep a hand on the wheel. Ask what the passengers say when the client turns toward the value.', '[{"id": "f0", "type": "textarea", "label": "Where I want my bus to go"}, {"id": "f1", "type": "textarea", "label": "My loudest passengers and what they say"}, {"id": "f2", "type": "textarea", "label": "What they want me to do instead"}, {"id": "f3", "type": "textarea", "label": "One turn toward my direction I can make this week"}, {"id": "f4", "type": "textarea", "label": "How I will drive with them aboard"}]'::jsonb, array['defusion', 'values', 'core ACT']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('willingness-dial-rating-page', 'Willingness Dial Rating Page', 'act'::resource_kind, 'A check-in where a client rates their willingness to feel something uncomfortable in order to do something that matters.', 'Use it to help a client notice and adjust willingness in the moment.', array['Adults']::text[], '20 minutes', 'Draw a dial from 0 to 10 and ask where the client sits about a specific action. If it is low, ask what would raise it by one point, not to ten. Willingness is a choice made again and again, not a feeling. Pair it with one small action to try between sessions.', '[{"id": "f0", "type": "textarea", "label": "The action that matters to me"}, {"id": "f1", "type": "textarea", "label": "What discomfort comes with it"}, {"id": "f2", "type": "textarea", "label": "My willingness today, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What would move it up one notch"}, {"id": "f4", "type": "textarea", "label": "The smallest version I would be willing to do"}]'::jsonb, array['willingness', 'acceptance', 'committed action']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('values-based-calendar-audit', 'Values-Based Calendar Audit', 'act'::resource_kind, 'A look at a client''s actual week to see which hours moved them toward a chosen value and which did not.', 'Use it to help a client line up how time is spent with what they value.', array['Adults']::text[], '30 minutes', 'Choose one value and mark the past week''s calendar for the times that served it. Avoid turning the audit into a verdict; the aim is to spot one place a small change fits. Ask what the client would be proud to put on the calendar next week.', '[{"id": "f0", "type": "textarea", "label": "A value I want more of"}, {"id": "f1", "type": "textarea", "label": "Times this week that served it"}, {"id": "f2", "type": "textarea", "label": "Times I drifted away from it"}, {"id": "f3", "type": "textarea", "label": "One block of time I can reclaim"}, {"id": "f4", "type": "textarea", "label": "What might pull me off course"}, {"id": "f5", "type": "textarea", "label": "Who can help me stay on course"}]'::jsonb, array['values', 'committed action', 'planning']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('leaves-on-a-stream-daily-log', 'Leaves on a Stream Daily Log', 'act'::resource_kind, 'A practice log for the leaves-on-a-stream exercise, recording what showed up and how the client returned to it.', 'Use it to help a client practice noticing thoughts and letting them pass.', array['Adults', 'Teens']::text[], 'Five minutes daily for a week', 'Walk the client through the exercise once in session so the log makes sense. They note what appeared on the leaves and how they noticed they had drifted. Reassure them that drifting off is part of it. Avoid asking for calm; ask what they noticed.', '[{"id": "f0", "type": "textarea", "label": "Day and length of practice"}, {"id": "f1", "type": "textarea", "label": "Thoughts or feelings that floated by"}, {"id": "f2", "type": "textarea", "label": "When I got caught up in one"}, {"id": "f3", "type": "textarea", "label": "How I came back"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the practice this week"}]'::jsonb, array['defusion', 'mindfulness', 'core ACT']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('the-struggle-switch-worksheet', 'The Struggle Switch Worksheet', 'act'::resource_kind, 'A worksheet on the struggle switch idea: how fighting a feeling can add a second layer of distress.', 'Use it to help a client see what struggling with a feeling costs them.', array['Adults']::text[], '25 minutes', 'Describe the switch in your own words and ask the client to find a recent time it was on. Look at what the struggle cost in time, energy or relationships. Then explore what turning it off might look like in one small way. Avoid promising the feeling will shrink.', '[{"id": "f0", "type": "textarea", "label": "A feeling I try hard to get rid of"}, {"id": "f1", "type": "textarea", "label": "What I do to fight it"}, {"id": "f2", "type": "textarea", "label": "What that costs me"}, {"id": "f3", "type": "textarea", "label": "What happens to the feeling when I fight it"}, {"id": "f4", "type": "textarea", "label": "One small way I could make room for it"}]'::jsonb, array['acceptance', 'willingness', 'core ACT']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('three-minds-pause-card', 'Three Minds Pause Card', 'dbt'::resource_kind, 'A pocket card with questions that help a client check whether emotion mind, reasonable mind or wise mind is leading.', 'Use it to help a client pause and find wise mind before acting.', array['Adults', 'Teens']::text[], '20 minutes', 'Teach the three states with an example from the client''s week, then have them fill the card. The card is for use in the moment, so keep the wording short enough to carry. Practice it once in session on a mild feeling. Ask which state tends to take over first.', '[{"id": "f0", "type": "textarea", "label": "What I am feeling right now"}, {"id": "f1", "type": "textarea", "label": "What my reasonable mind says"}, {"id": "f2", "type": "textarea", "label": "What my emotion mind wants to do"}, {"id": "f3", "type": "textarea", "label": "What my wise mind says"}, {"id": "f4", "type": "textarea", "label": "One breath and one step I will take"}]'::jsonb, array['core DBT', 'mindfulness', 'regulation']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('opposite-action-trial-log', 'Opposite Action Trial Log', 'dbt'::resource_kind, 'A log for trying the opposite of an urge that does not fit the facts and noting what happened.', 'Use it to help a client try opposite action and see its effect.', array['Adults', 'Teens']::text[], 'One week', 'Choose an emotion whose urge does not fit the facts, such as withdrawing when it would help to reach out. The client plans the opposite action, does it all the way, and records the feeling before and after. Check that the emotion really does not fit; some do and need a different skill.', '[{"id": "f0", "type": "textarea", "label": "The emotion and its urge"}, {"id": "f1", "type": "textarea", "label": "Does the urge fit the facts? Why or why not"}, {"id": "f2", "type": "textarea", "label": "The opposite action I chose"}, {"id": "f3", "type": "textarea", "label": "How fully I did it"}, {"id": "f4", "type": "textarea", "label": "My feeling before and after"}, {"id": "f5", "type": "textarea", "label": "What I would try again"}]'::jsonb, array['emotion regulation', 'core DBT', 'behavioral activation']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('tipp-skills-practice-planner', 'TIPP Skills Practice Planner', 'dbt'::resource_kind, 'A planner for practicing temperature, intense exercise, paced breathing and muscle relaxation before they are needed.', 'Use it to help a client rehearse TIPP skills when calm.', array['Adults', 'Teens']::text[], '30 minutes', 'Go through each skill in session if safe for the client, and check anything medical first, such as heart conditions or cold sensitivity. The client picks the one they would actually use and writes where to keep the supplies. Practice when calm so it is there when needed.', '[{"id": "f0", "type": "textarea", "label": "Which TIPP skills I will try"}, {"id": "f1", "type": "textarea", "label": "What I need on hand for each"}, {"id": "f2", "type": "textarea", "label": "When I will practice this week"}, {"id": "f3", "type": "textarea", "label": "How I will know it is time to use one"}, {"id": "f4", "type": "textarea", "label": "Which worked best and why"}]'::jsonb, array['distress tolerance', 'core DBT', 'skills']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('six-levels-of-validation-rehearsal', 'Six Levels of Validation Rehearsal', 'dbt'::resource_kind, 'A sheet for practicing the levels of validation with a real or imagined conversation.', 'Use it to help a client practice validating another person and themselves.', array['Adults', 'Couples']::text[], '25 minutes', 'Name the levels briefly, then have the client write what each would sound like in a recent conversation. Many clients confuse validating with agreeing; make the difference plain. Role-play one level in session and ask how it felt to receive it.', '[{"id": "f0", "type": "textarea", "label": "A recent conversation I want to look at"}, {"id": "f1", "type": "textarea", "label": "What I could say to show I am listening"}, {"id": "f2", "type": "textarea", "label": "What I could say to name their feeling"}, {"id": "f3", "type": "textarea", "label": "What I could say that makes sense given their situation"}, {"id": "f4", "type": "textarea", "label": "How I could validate myself the same way"}]'::jsonb, array['interpersonal effectiveness', 'connection', 'core DBT']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('accept-and-cope-ahead-page', 'Accept and Cope Ahead Page', 'dbt'::resource_kind, 'A page that pairs a situation a client cannot change with a plan for accepting it and coping ahead.', 'Use it to help a client rehearse acceptance of a painful fact.', array['Adults']::text[], '30 minutes', 'Pick a fact the client keeps fighting. Have them write what accepting it would sound like, then plan how they will cope when it comes up again. Acceptance is not approval; say so. If grief surfaces, slow down and let it be there before moving to the plan.', '[{"id": "f0", "type": "textarea", "label": "The fact I keep fighting"}, {"id": "f1", "type": "textarea", "label": "What fighting it costs me"}, {"id": "f2", "type": "textarea", "label": "What acceptance would sound like"}, {"id": "f3", "type": "textarea", "label": "When it will come up next"}, {"id": "f4", "type": "textarea", "label": "How I will cope ahead"}, {"id": "f5", "type": "textarea", "label": "Who I can lean on"}]'::jsonb, array['acceptance', 'distress tolerance', 'core DBT']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('weekly-appreciation-and-request-exchange', 'Weekly Appreciation and Request Exchange', 'couples'::resource_kind, 'A short weekly exchange where each partner shares two appreciations and one specific, doable request.', 'Use it to help partners build a regular habit of noticing and asking.', array['Couples']::text[], '20 minutes', 'Partners take turns, one speaking while the other only listens and then thanks them. Requests must be specific and doable this week, not complaints in disguise. Model it first. If one partner has no appreciations, slow down and ask what small thing happened this week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: two things I appreciated this week"}, {"id": "f1", "type": "textarea", "label": "Partner B: two things I appreciated this week"}, {"id": "f2", "type": "textarea", "label": "Partner A: one request for this week"}, {"id": "f3", "type": "textarea", "label": "Partner B: one request for this week"}, {"id": "f4", "type": "textarea", "label": "Together: when we will do this again"}]'::jsonb, array['communication', 'connection', 'couples']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('daily-stress-talk-guide-for-partners', 'Daily Stress Talk Guide for Partners', 'couples'::resource_kind, 'A guide for a daily talk where partners help each other with outside stress without trying to fix it.', 'Use it to help partners support each other through stress from outside the relationship.', array['Couples']::text[], '25 minutes', 'Each partner talks about a stressor outside the relationship for about ten minutes while the other asks questions and shows interest, with no advice unless asked. Many couples slip into problem-solving; name that gently. Debrief on what felt supportive.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a stress I am carrying"}, {"id": "f1", "type": "textarea", "label": "Partner B: a stress I am carrying"}, {"id": "f2", "type": "textarea", "label": "What helped me feel heard"}, {"id": "f3", "type": "textarea", "label": "What I would like less of"}, {"id": "f4", "type": "textarea", "label": "One way we can support each other this week"}]'::jsonb, array['Gottman', 'support', 'communication']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('shared-meaning-rituals-brainstorm', 'Shared Meaning Rituals Brainstorm', 'couples'::resource_kind, 'A brainstorm of small rituals, such as meals, greetings and weekends, that make a shared life feel like ours.', 'Use it to help partners create or revive rituals that connect them.', array['Couples']::text[], '30 minutes', 'Ask each partner to write rituals from their families growing up and ones they would like now. Look for one overlap to try this week. Avoid grand plans; small and repeatable wins. Revisit in two weeks and keep what they enjoy.', '[{"id": "f0", "type": "textarea", "label": "Partner A: rituals I remember and liked"}, {"id": "f1", "type": "textarea", "label": "Partner B: rituals I remember and liked"}, {"id": "f2", "type": "textarea", "label": "Rituals we already have that I love"}, {"id": "f3", "type": "textarea", "label": "One new ritual I would like us to try"}, {"id": "f4", "type": "textarea", "label": "When and how we will start"}]'::jsonb, array['connection', 'rituals', 'couples']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('dreams-within-conflict-exploration', 'Dreams Within Conflict Exploration', 'couples'::resource_kind, 'An exploration of the dream or hope underneath a recurring disagreement, told by each partner in turn.', 'Use it to help partners hear what a stuck argument is really about.', array['Couples']::text[], 'Full session', 'Choose a disagreement that keeps returning. Each partner explains what the position means to them, the story or value behind it, while the other asks open questions. The goal is understanding, not agreement. Stop and regroup if either partner becomes flooded.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my position on the issue"}, {"id": "f1", "type": "textarea", "label": "Partner A: what it means to me and where it comes from"}, {"id": "f2", "type": "textarea", "label": "Partner B: my position on the issue"}, {"id": "f3", "type": "textarea", "label": "Partner B: what it means to me and where it comes from"}, {"id": "f4", "type": "textarea", "label": "Something we can honor in both"}, {"id": "f5", "type": "textarea", "label": "A small step we can agree to try"}]'::jsonb, array['conflict', 'Gottman', 'understanding']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('mid-argument-repair-menu', 'Mid-Argument Repair Menu', 'couples'::resource_kind, 'A menu of phrases and gestures partners can use to repair in the middle of an argument.', 'Use it to help partners agree ahead of time on how to call a pause or soften.', array['Couples']::text[], '20 minutes', 'Partners each write phrases and gestures that would help them soften in the heat of an argument, then trade lists and pick favorites. Agree on one signal for a break and a time to come back. Rehearse one in session with something low-stakes.', '[{"id": "f0", "type": "textarea", "label": "Partner A: words that help me soften"}, {"id": "f1", "type": "textarea", "label": "Partner B: words that help me soften"}, {"id": "f2", "type": "textarea", "label": "Partner A: gestures that help me"}, {"id": "f3", "type": "textarea", "label": "Partner B: gestures that help me"}, {"id": "f4", "type": "textarea", "label": "Our signal for a break"}, {"id": "f5", "type": "textarea", "label": "How long we wait before we return"}]'::jsonb, array['repair', 'conflict', 'communication']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('feelings-weather-window-picture', 'Feelings Weather Window Picture', 'kids'::resource_kind, 'A craft where a child draws a window and fills it with the weather that matches how they feel today.', 'Use it to give a child a simple picture for naming feelings.', array['Children']::text[], '25 minutes', 'Give the child paper, crayons and a cut-out window frame. They draw today''s feeling weather and tell you about it. The parent watches, then adds a small weather card of their own. Keep it light and playful, and praise the telling, not the picture.', '[{"id": "f0", "type": "textarea", "label": "Draw the weather inside me today"}, {"id": "f1", "type": "textarea", "label": "What kind of weather is it?"}, {"id": "f2", "type": "textarea", "label": "What would make the weather change?"}, {"id": "f3", "type": "textarea", "label": "Who can I tell when it storms?"}]'::jsonb, array['emotion identification', 'art', 'children']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('calm-down-jar-building-activity', 'Calm-Down Jar Building Activity', 'kids'::resource_kind, 'A hands-on activity where a child builds a glitter jar and uses it for a calm pause.', 'Use it to give a child a physical tool for slowing down.', array['Children']::text[], '30 minutes', 'Build the jar together with a clear bottle, warm water, glue and glitter. The child shakes it and watches it settle while breathing slowly. The parent practices with them and keeps the jar somewhere easy to reach. Present it as a pause, never as a punishment.', '[{"id": "f0", "type": "textarea", "label": "Draw my calm-down jar"}, {"id": "f1", "type": "textarea", "label": "What do I notice when the glitter falls?"}, {"id": "f2", "type": "textarea", "label": "When could I use my jar?"}, {"id": "f3", "type": "textarea", "label": "Who will practice with me?"}]'::jsonb, array['calming', 'regulation', 'play']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('brave-staircase-picture-plan', 'Brave Staircase Picture Plan', 'kids'::resource_kind, 'A drawing of a staircase where each step is a small brave thing a child wants to try.', 'Use it to help a child plan small brave steps one at a time.', array['Children']::text[], '25 minutes', 'The child draws a staircase and names the top step as the big goal. Together you fill in smaller steps below it. The parent says one step they will cheer for. Choose a first step the child is willing to try this week and celebrate it, however small.', '[{"id": "f0", "type": "textarea", "label": "Draw my staircase"}, {"id": "f1", "type": "textarea", "label": "The big brave thing at the top"}, {"id": "f2", "type": "textarea", "label": "The first small step at the bottom"}, {"id": "f3", "type": "textarea", "label": "Who will cheer for me?"}]'::jsonb, array['exposure', 'courage', 'drawing']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('kindness-garden-planting-game', 'Kindness Garden Planting Game', 'kids'::resource_kind, 'A pretend garden where each kind act a child does grows a paper flower.', 'Use it to help a child notice and enjoy kind acts.', array['Children']::text[], '25 minutes', 'Draw a big garden bed. Each time the child does or notices a kind act that week, they add a paper flower. The parent helps spot acts and adds some of their own. At the next visit, count the flowers and talk about the one the child liked most.', '[{"id": "f0", "type": "textarea", "label": "Draw my garden"}, {"id": "f1", "type": "textarea", "label": "A kind thing I did"}, {"id": "f2", "type": "textarea", "label": "A kind thing someone did for me"}, {"id": "f3", "type": "textarea", "label": "How it felt to give or get a flower"}]'::jsonb, array['kindness', 'connection', 'play']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('worry-monster-snack-box-craft', 'Worry Monster Snack Box Craft', 'kids'::resource_kind, 'A craft where a child decorates a box for a friendly monster that holds their written or drawn worries.', 'Use it to give a child a safe, playful place to put worries.', array['Children']::text[], '30 minutes', 'Decorate a small box with eyes and a mouth slot. The child draws or tells a worry and feeds it to the monster, then picks a time to open the box with a parent. Never force a worry; let them choose. The parent listens and thanks the monster.', '[{"id": "f0", "type": "textarea", "label": "Draw my worry monster"}, {"id": "f1", "type": "textarea", "label": "A worry I am feeding it today"}, {"id": "f2", "type": "textarea", "label": "What the monster says back"}, {"id": "f3", "type": "textarea", "label": "What I can do when I feel it"}]'::jsonb, array['worry', 'art', 'children']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('skills-bingo-card-game', 'Skills Bingo Card Game', 'game'::resource_kind, 'A bingo game where each square is a coping skill and players mark squares as they describe using one.', 'Use it to help a group recall and talk about the skills they use.', array['Teens', 'Groups']::text[], '30 minutes', 'Make cards with skills in the squares. Players take turns telling when they used a skill or when they could, and mark a square. First to complete a line shares a favorite skill. Debrief by asking which squares were easiest and hardest to fill.', '[{"id": "f0", "type": "textarea", "label": "Skills I marked off"}, {"id": "f1", "type": "textarea", "label": "One I used this week"}, {"id": "f2", "type": "textarea", "label": "One I want to try"}, {"id": "f3", "type": "textarea", "label": "What I learned from others"}]'::jsonb, array['skills', 'group', 'coping skills']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('two-truths-and-a-strength-round', 'Two Truths and a Strength Round', 'game'::resource_kind, 'A round of two true statements and one strength a player has, with the group guessing which is the strength.', 'Use it to help group members name strengths in a light, playful way.', array['Teens', 'Groups']::text[], '20 minutes', 'Each player writes two ordinary truths about themselves and one strength, then reads them aloud in any order while the group guesses the strength. Keep guesses kind. Debrief by asking how it felt to say a strength out loud and what surprised them.', '[{"id": "f0", "type": "textarea", "label": "My two truths"}, {"id": "f1", "type": "textarea", "label": "My strength"}, {"id": "f2", "type": "textarea", "label": "What I learned about someone else"}, {"id": "f3", "type": "textarea", "label": "How it felt to name a strength"}]'::jsonb, array['strengths', 'group', 'self-esteem']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('emotion-charades-challenge', 'Emotion Charades Challenge', 'game'::resource_kind, 'A charades game where players act out feelings and others guess, then talk about when they feel them.', 'Use it to help children and teens name feelings with their bodies and voices.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Write feelings on cards. Players act one without words while others guess, then share a time someone might feel that way. Rotate turns and keep it playful. Debrief by asking which feeling was hardest to act or to guess.', '[{"id": "f0", "type": "textarea", "label": "A feeling I acted"}, {"id": "f1", "type": "textarea", "label": "How my body showed it"}, {"id": "f2", "type": "textarea", "label": "A time I felt it"}, {"id": "f3", "type": "textarea", "label": "A feeling that was hard to guess"}]'::jsonb, array['emotion identification', 'play', 'group']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('many-ideas-relay-game', 'Many Ideas Relay Game', 'game'::resource_kind, 'A team relay where each player adds one idea to solve a pretend problem before passing the baton.', 'Use it to help a group practice generating several solutions to a problem.', array['Teens', 'Groups']::text[], '30 minutes', 'Give each team a problem card. Players pass a baton, and each adds one idea, silly or sensible, before passing. After time, teams pick their favorite and explain why. Debrief by asking how coming up with many ideas changed how stuck they felt.', '[{"id": "f0", "type": "textarea", "label": "The problem my team got"}, {"id": "f1", "type": "textarea", "label": "An idea I added"}, {"id": "f2", "type": "textarea", "label": "The idea we chose and why"}, {"id": "f3", "type": "textarea", "label": "How I can use this on a real problem"}]'::jsonb, array['problem solving', 'group', 'skills']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('calm-dice-challenge', 'Calm Dice Challenge', 'game'::resource_kind, 'A dice game where each number matches a calming activity players try for one minute.', 'Use it to help players try different calming activities in a fun way.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Make a list of six calming activities, such as breathing, stretching, naming five sounds. A player rolls, does the matching activity for a minute and rates how they feel. Take turns. Debrief by asking which activities were helpful to try again.', '[{"id": "f0", "type": "textarea", "label": "The activity I rolled"}, {"id": "f1", "type": "textarea", "label": "How I felt before and after"}, {"id": "f2", "type": "textarea", "label": "My favorite activity"}, {"id": "f3", "type": "textarea", "label": "Where I could use it"}]'::jsonb, array['calming', 'regulation', 'play']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('safe-place-senses-builder', 'Safe Place Senses Builder', 'worksheet'::resource_kind, 'A page for building a calm, safe place in the imagination with sights, sounds and textures.', 'Use it to give a client a steady inner place to return to.', array['Adults', 'Teens']::text[], '25 minutes', 'Build the place in session at the client''s pace, and let them stop at any moment. Choose a place that is neutral or pleasant, not tied to a person who may be complicated. Keep to the present and the senses; no memories of events are needed. Practice returning to it briefly each session.', '[{"id": "f0", "type": "textarea", "label": "Where my safe place is"}, {"id": "f1", "type": "textarea", "label": "What I see there"}, {"id": "f2", "type": "textarea", "label": "What I hear"}, {"id": "f3", "type": "textarea", "label": "What I feel against my skin"}, {"id": "f4", "type": "textarea", "label": "What I smell or taste"}, {"id": "f5", "type": "textarea", "label": "A word that brings me back to it"}]'::jsonb, array['PTSD and trauma', 'grounding', 'safety']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('window-of-tolerance-zone-map', 'Window of Tolerance Zone Map', 'cbt'::resource_kind, 'A map where a client marks signs of being too revved up, too shut down or steady, and what helps in each zone.', 'Use it to help a client notice which zone they are in and what helps.', array['Adults']::text[], '30 minutes', 'Draw three bands and have the client place their own signs in each: body, thoughts, behavior. Then list what helps them move back toward steady. Stay with signs and skills only; there is no need to describe past events. Check in about the map each week.', '[{"id": "f0", "type": "textarea", "label": "Signs that I am too revved up"}, {"id": "f1", "type": "textarea", "label": "Signs that I am shut down"}, {"id": "f2", "type": "textarea", "label": "Signs that I am steady"}, {"id": "f3", "type": "textarea", "label": "What helps when I am revved up"}, {"id": "f4", "type": "textarea", "label": "What helps when I am shut down"}, {"id": "f5", "type": "textarea", "label": "One person I can contact"}]'::jsonb, array['PTSD and trauma', 'regulation', 'psychoeducation']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('reminder-cards-for-present-moment-orientation', 'Reminder Cards for Present-Moment Orientation', 'dbt'::resource_kind, 'Pocket cards that help a client remind themselves of the date, place and what is safe right now.', 'Use it to help a client orient to the present when reminders pull them away.', array['Adults']::text[], '20 minutes', 'Write cards with the client: today''s date, where I am, what I can see that is different from before. Role-play pulling one out. Keep cards short and kind. Pair them with a skill such as paced breathing and invite the client to adjust wording until it feels true.', '[{"id": "f0", "type": "textarea", "label": "Today''s date and where I am"}, {"id": "f1", "type": "textarea", "label": "Three things I can see that are here and now"}, {"id": "f2", "type": "textarea", "label": "What is safe about right now"}, {"id": "f3", "type": "textarea", "label": "A skill I will use next"}, {"id": "f4", "type": "textarea", "label": "A kind sentence to say to myself"}]'::jsonb, array['PTSD and trauma', 'grounding', 'distress tolerance']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('values-compass-for-rebuilding', 'Values Compass for Rebuilding', 'act'::resource_kind, 'A compass that points a client toward what matters to them now, at their own pace and without retelling events.', 'Use it to help a client reconnect with values and small actions.', array['Adults']::text[], '30 minutes', 'Invite the client to name a few values and one small action for each this week. Do not ask for the story of what happened. Notice if the discussion pulls them into distress and pause for grounding. Keep the action small, safe and chosen by them.', '[{"id": "f0", "type": "textarea", "label": "Something that matters to me"}, {"id": "f1", "type": "textarea", "label": "A tiny action that fits it"}, {"id": "f2", "type": "textarea", "label": "What might get in the way"}, {"id": "f3", "type": "textarea", "label": "What I need to feel safe doing it"}, {"id": "f4", "type": "textarea", "label": "Who can support me"}]'::jsonb, array['PTSD and trauma', 'values', 'committed action']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('here-and-now-scavenger-hunt', 'Here-and-Now Scavenger Hunt', 'game'::resource_kind, 'A game of finding things in the room by color, texture or sound to bring attention to the present.', 'Use it to give a client or group a playful way to practice grounding.', array['Teens', 'Groups']::text[], '20 minutes', 'Call out clues such as something blue, something soft, something that makes a sound. Players find and describe items, then rate how steady they feel. Keep it voluntary and let anyone pass. Debrief by asking which clue helped most and when they could use it.', '[{"id": "f0", "type": "textarea", "label": "What I found"}, {"id": "f1", "type": "textarea", "label": "Which clue helped me most"}, {"id": "f2", "type": "textarea", "label": "How steady I feel, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Where I could use this at home"}]'::jsonb, array['PTSD and trauma', 'grounding', 'skills']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('worry-time-boundary-planner', 'Worry Time Boundary Planner', 'cbt'::resource_kind, 'A planner for setting a short daily worry window and parking worries outside it.', 'Use it to help a client contain worry to a set time.', array['Adults']::text[], '25 minutes', 'Choose a 15-minute slot that is not near bedtime. During the day the client jots a worry on a parking list and returns to it in the window, then notes which still matter. Clients often find many have faded. Do not demand that they stop worrying; just move it.', '[{"id": "f0", "type": "textarea", "label": "My worry window time and place"}, {"id": "f1", "type": "textarea", "label": "Worries I parked today"}, {"id": "f2", "type": "textarea", "label": "Which still matter in the window"}, {"id": "f3", "type": "textarea", "label": "One I can act on"}, {"id": "f4", "type": "textarea", "label": "One I can let go for now"}]'::jsonb, array['anxiety', 'worry', 'planning']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('anxious-thoughts-as-weather-act-page', 'Anxious Thoughts as Weather ACT Page', 'act'::resource_kind, 'A page using weather as an image for anxious thoughts that come and go.', 'Use it to help a client treat anxious thoughts as passing weather.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to describe the forecast in their head today, then name what they can do whatever the weather. Weather metaphors can seem simple; invite them to adjust the image so it fits. Close with one action toward a value they will take even if clouds remain.', '[{"id": "f0", "type": "textarea", "label": "Today''s forecast in my mind"}, {"id": "f1", "type": "textarea", "label": "What the clouds say"}, {"id": "f2", "type": "textarea", "label": "What I want to do anyway"}, {"id": "f3", "type": "textarea", "label": "A value I am heading toward"}, {"id": "f4", "type": "textarea", "label": "One step I can take in any weather"}]'::jsonb, array['anxiety', 'defusion', 'values']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('worry-tummy-helper-drawing', 'Worry Tummy Helper Drawing', 'kids'::resource_kind, 'A drawing where a child shows where worry lives in the body and draws a helper to calm it.', 'Use it to help a child connect body feelings with worry and calming helpers.', array['Children']::text[], '25 minutes', 'Have the child draw an outline of a body and color where worry shows up. Then draw a helper, such as a deep breath or a hug. The parent learns the child''s signals and practices the helper with them. Keep it playful and accept the child''s picture as it is.', '[{"id": "f0", "type": "textarea", "label": "Color where worry lives in my body"}, {"id": "f1", "type": "textarea", "label": "Draw my helper"}, {"id": "f2", "type": "textarea", "label": "What my helper does"}, {"id": "f3", "type": "textarea", "label": "Who can help me use it"}]'::jsonb, array['anxiety', 'emotion identification', 'children']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('anxiety-early-signals-tracker', 'Anxiety Early Signals Tracker', 'worksheet'::resource_kind, 'A tracker for the body, thought and behavior signs that show up early, before anxiety builds.', 'Use it to help a client catch anxiety signals sooner.', array['Adults', 'Teens']::text[], 'One week', 'The client notes each time they notice rising anxiety, what the first signal was and what they did. Look for patterns in timing and place. This is about noticing, not rating or judging. Share what stands out and pick one early signal to respond to differently next week.', '[{"id": "f0", "type": "textarea", "label": "Date and time I noticed it"}, {"id": "f1", "type": "textarea", "label": "The first signal I noticed"}, {"id": "f2", "type": "textarea", "label": "What was going on around me"}, {"id": "f3", "type": "textarea", "label": "What I did"}, {"id": "f4", "type": "textarea", "label": "What I might try earlier next time"}]'::jsonb, array['anxiety', 'self-monitoring', 'regulation']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('anxiety-uncertainty-dice-game', 'Anxiety Uncertainty Dice Game', 'game'::resource_kind, 'A game where each roll names a small uncertain situation and players practice saying a coping statement.', 'Use it to help players practice tolerating small uncertainties with humor.', array['Teens', 'Groups']::text[], '25 minutes', 'Make six cards of ordinary uncertain situations, such as not knowing what is for dinner. Players roll, read the card and say how they would handle it. The group offers kind statements. Debrief by asking where in life they notice the same pull to know for sure.', '[{"id": "f0", "type": "textarea", "label": "The uncertain thing I rolled"}, {"id": "f1", "type": "textarea", "label": "My coping statement"}, {"id": "f2", "type": "textarea", "label": "One real uncertainty this week"}, {"id": "f3", "type": "textarea", "label": "How I can handle it"}]'::jsonb, array['anxiety', 'uncertainty', 'group']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('small-joys-spotting-log', 'Small Joys Spotting Log', 'cbt'::resource_kind, 'A log where a client records one small pleasant moment each day and the thought that went with it.', 'Use it to help a client notice pleasant moments that low mood can hide.', array['Adults']::text[], 'One week', 'Start by saying that the goal is to notice, not to feel great. The client logs one small moment a day, such as warm tea or a text from a friend. Review which moments mattered and plan to add one on purpose. Be ready for days with nothing; that is information.', '[{"id": "f0", "type": "textarea", "label": "Today''s small moment"}, {"id": "f1", "type": "textarea", "label": "What was happening"}, {"id": "f2", "type": "textarea", "label": "What I felt in my body"}, {"id": "f3", "type": "textarea", "label": "What I thought"}, {"id": "f4", "type": "textarea", "label": "One I could add on purpose tomorrow"}]'::jsonb, array['depression', 'behavioral activation', 'self-monitoring']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('low-energy-day-menu-2', 'Low Energy Day Menu', 'worksheet'::resource_kind, 'A menu of tiny actions a client can pick from on days when energy is very low.', 'Use it to give a client a short list of doable actions for hard days.', array['Adults', 'Teens']::text[], '25 minutes', 'Write the menu together with actions that take five minutes or less: a glass of water, step outside, one text. The client chooses one, not all. If the client mentions thoughts of ending their life, follow your usual steps and remind them 988 (call or text) is available any time.', '[{"id": "f0", "type": "textarea", "label": "Things that take under five minutes"}, {"id": "f1", "type": "textarea", "label": "One for my body"}, {"id": "f2", "type": "textarea", "label": "One for connection"}, {"id": "f3", "type": "textarea", "label": "One for my space"}, {"id": "f4", "type": "textarea", "label": "Which I will pick on my next hard day"}, {"id": "f5", "type": "textarea", "label": "Who I could tell: 988 (call or text) is there any time"}]'::jsonb, array['depression', 'behavioral activation', 'routines']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('self-kindness-letter-planner', 'Self-Kindness Letter Planner', 'act'::resource_kind, 'A planner for writing a short letter from a caring friend''s point of view to the client themselves.', 'Use it to help a client practice a kinder voice toward themselves.', array['Adults']::text[], '30 minutes', 'Ask the client to imagine a friend who knows their struggles and cares. They write what that friend would say. Some find this hard; offer sentence starters. Do not insist on a certain tone. Read it aloud if they are willing and ask how it lands.', '[{"id": "f0", "type": "textarea", "label": "Someone who cares about me"}, {"id": "f1", "type": "textarea", "label": "What they would notice I am going through"}, {"id": "f2", "type": "textarea", "label": "What they would say about my effort"}, {"id": "f3", "type": "textarea", "label": "What they would encourage me to do"}, {"id": "f4", "type": "textarea", "label": "How I feel after reading it"}]'::jsonb, array['depression', 'self-compassion', 'values']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('mood-and-activity-link-chart', 'Mood and Activity Link Chart', 'dbt'::resource_kind, 'A chart linking activities to mood so a client can pick actions that build a sense of mastery or pleasure.', 'Use it to help a client see which activities lift mood and plan more.', array['Adults', 'Teens']::text[], 'One week', 'The client records activities and tags each as pleasure or mastery, with a mood rating. Review what stands out and plan two more of the best ones. Resist saying they should feel better; let the pattern speak. Adjust choices if energy is low.', '[{"id": "f0", "type": "textarea", "label": "Activity and time"}, {"id": "f1", "type": "textarea", "label": "Pleasure or mastery"}, {"id": "f2", "type": "textarea", "label": "Mood before and after"}, {"id": "f3", "type": "textarea", "label": "What stands out"}, {"id": "f4", "type": "textarea", "label": "Two I will plan for next week"}]'::jsonb, array['depression', 'emotion regulation', 'mastery']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('partner-support-for-low-mood-plan', 'Partner Support for Low Mood Plan', 'couples'::resource_kind, 'A plan for partners to agree on how one can support the other on low days without pressure.', 'Use it to help partners agree on helpful support for low mood.', array['Couples']::text[], '30 minutes', 'The partner with low mood says what helps and what does not. The other says what they can offer and what they need for themselves. Agree on one daily check-in. Keep blame out of it. If either mentions thoughts of ending their life, say 988 (call or text) is there any time and follow your usual steps.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps on low days"}, {"id": "f1", "type": "textarea", "label": "Partner A: what does not help"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I can offer"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need for myself"}, {"id": "f4", "type": "textarea", "label": "A check-in we both can keep"}, {"id": "f5", "type": "textarea", "label": "If it feels like too much: 988 (call or text)"}]'::jsonb, array['depression', 'support', 'couples']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('task-start-ramp-worksheet', 'Task Start Ramp Worksheet', 'worksheet'::resource_kind, 'A worksheet that breaks the first five minutes of a task into a ramp of tiny steps.', 'Use it to help a client get started on a task they keep putting off.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick one task. Write the first physical action, such as opening the document or putting on shoes, then a two-minute version and a five-minute version. Add a cue and a reward. Clients often plan the whole project; keep them to the first ramp.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off"}, {"id": "f1", "type": "textarea", "label": "The first physical action"}, {"id": "f2", "type": "textarea", "label": "A two-minute version"}, {"id": "f3", "type": "textarea", "label": "A cue that will remind me"}, {"id": "f4", "type": "textarea", "label": "A small reward after"}, {"id": "f5", "type": "textarea", "label": "Who can check in with me"}]'::jsonb, array['ADHD', 'planning', 'routines']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('dragon-chase-time-game-for-kids', 'Dragon Chase Time Game for Kids', 'kids'::resource_kind, 'A play activity where a child races a timer dragon to finish one small task and earns a sticker.', 'Use it to help a child practice finishing short tasks with a playful timer.', array['Children']::text[], '20 minutes', 'Draw a dragon on a card and set a visual timer. The child works on one small job, like putting toys in a bin, before the dragon arrives. The parent cheers and notes what worked. Keep the task short and the tone fun, never a race against shame.', '[{"id": "f0", "type": "textarea", "label": "Draw my dragon"}, {"id": "f1", "type": "textarea", "label": "The small job I did"}, {"id": "f2", "type": "textarea", "label": "How much time I used"}, {"id": "f3", "type": "textarea", "label": "What helped me keep going"}]'::jsonb, array['ADHD', 'play', 'routines']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('body-doubling-check-in-game', 'Body Doubling Check-In Game', 'game'::resource_kind, 'A game where players work alongside a partner on separate tasks and check in with a score.', 'Use it to help players try body doubling and see if company helps focus.', array['Teens', 'Groups']::text[], '25 minutes', 'Pair players. Each names a task, works for ten minutes in the same room, and then checks in for a minute. Switch roles. Debrief by asking what changed with another person nearby and whether they could arrange it at home.', '[{"id": "f0", "type": "textarea", "label": "My task"}, {"id": "f1", "type": "textarea", "label": "How focused I was, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What my partner did that helped"}, {"id": "f3", "type": "textarea", "label": "Where I could use a work buddy"}]'::jsonb, array['ADHD', 'support', 'group']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('working-memory-cue-plan', 'Working Memory Cue Plan', 'cbt'::resource_kind, 'A plan for putting reminders where the client will see them at the moment they need them.', 'Use it to help a client set up visible cues for things they forget.', array['Adults', 'Teens']::text[], '25 minutes', 'List things that get forgotten and for each decide the point of use: the door, the phone, the bed. Reminders hidden in notes do not help; place them where the action happens. Test one cue for a week and adjust. Avoid framing forgetting as a flaw.', '[{"id": "f0", "type": "textarea", "label": "Things I often forget"}, {"id": "f1", "type": "textarea", "label": "Where I need to remember them"}, {"id": "f2", "type": "textarea", "label": "A cue I can put there"}, {"id": "f3", "type": "textarea", "label": "What might block the cue"}, {"id": "f4", "type": "textarea", "label": "How I will check if it works"}]'::jsonb, array['ADHD', 'planning', 'self-monitoring']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('shared-household-task-board-for-partners', 'Shared Household Task Board for Partners', 'couples'::resource_kind, 'A board where partners list household tasks, who does them and a visible way to track them.', 'Use it to help partners share tasks without nagging.', array['Couples']::text[], '30 minutes', 'Partners list household tasks and mark who does which, aiming for fairness as they define it. Use a visible board so memory does not carry the load. Agree on how reminders will be given, with a request instead of a complaint. Review in two weeks.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I do now"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I do now"}, {"id": "f2", "type": "textarea", "label": "Tasks that fall through"}, {"id": "f3", "type": "textarea", "label": "How we will make them visible"}, {"id": "f4", "type": "textarea", "label": "How we will remind each other kindly"}]'::jsonb, array['ADHD', 'communication', 'couples']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('urge-surfing-notes-sheet', 'Urge Surfing Notes Sheet', 'dbt'::resource_kind, 'A sheet for noting the rise and fall of an urge and what the client did while it passed.', 'Use it to help a client ride out urges for substance use.', array['Adults']::text[], 'One week', 'The client notes each urge''s start, peak and ending, plus what they did. Emphasize that urges rise, peak and fall. Don''t judge a use; look at what was different when they waited. If someone feels unsafe, follow your usual steps and name 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "When the urge started"}, {"id": "f1", "type": "textarea", "label": "What triggered it"}, {"id": "f2", "type": "textarea", "label": "How strong, 0 to 10, at its peak"}, {"id": "f3", "type": "textarea", "label": "What I did while it passed"}, {"id": "f4", "type": "textarea", "label": "How it changed"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe: 988 (call or text)"}]'::jsonb, array['addiction', 'urges', 'distress tolerance']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('reasons-and-values-for-change-page', 'Reasons and Values for Change Page', 'act'::resource_kind, 'A page connecting a client''s reasons for change around substance use to what they value.', 'Use it to help a client reconnect with why change matters to them.', array['Adults']::text[], '30 minutes', 'Ask the client what they want their life to stand for, then link it to choices about substance use. Avoid labels for people; speak about the substance use and urges. Ambivalence is welcome; ask what the part that wants to keep using is protecting.', '[{"id": "f0", "type": "textarea", "label": "What matters most to me"}, {"id": "f1", "type": "textarea", "label": "How substance use fits or clashes with that"}, {"id": "f2", "type": "textarea", "label": "Reasons I want change"}, {"id": "f3", "type": "textarea", "label": "What a part of me worries about"}, {"id": "f4", "type": "textarea", "label": "One step toward what matters"}]'::jsonb, array['addiction', 'values', 'willingness']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('trigger-chain-analysis-sheet', 'Trigger Chain Analysis Sheet', 'cbt'::resource_kind, 'A sheet that traces a day when substance use happened, link by link, to find a point where a different choice was possible.', 'Use it to help a client find places to intervene in a chain of events.', array['Adults']::text[], '30 minutes', 'Go step by step through what came before: events, feelings, thoughts, urges. Keep a kind, curious tone; shame shuts the conversation down. Choose one link where a different move could be tried, and plan it. Do not require full disclosure.', '[{"id": "f0", "type": "textarea", "label": "The situation that began it"}, {"id": "f1", "type": "textarea", "label": "Feelings and thoughts that came next"}, {"id": "f2", "type": "textarea", "label": "The urge"}, {"id": "f3", "type": "textarea", "label": "What I did"}, {"id": "f4", "type": "textarea", "label": "A link where I could do something different"}, {"id": "f5", "type": "textarea", "label": "What I need to try it"}]'::jsonb, array['addiction', 'urges', 'self-monitoring']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('recovery-day-structure-planner', 'Recovery Day Structure Planner', 'worksheet'::resource_kind, 'A planner for laying out a day with hour blocks for routine, support and activities that do not involve substance use.', 'Use it to help a client fill risky hours with planned activity.', array['Adults']::text[], '25 minutes', 'Mark the hours in which urges have been strongest and plan something specific for each. Include meals, movement, contact with support and rest. Avoid overfilling. Review next session, noting what held and what did not without judgment.', '[{"id": "f0", "type": "textarea", "label": "Hours when urges are strongest"}, {"id": "f1", "type": "textarea", "label": "What I will do in those hours"}, {"id": "f2", "type": "textarea", "label": "Who I can contact"}, {"id": "f3", "type": "textarea", "label": "Healthy routines I will keep"}, {"id": "f4", "type": "textarea", "label": "What I will change if the plan slips"}]'::jsonb, array['addiction', 'routines', 'planning']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('rebuilding-trust-conversation-guide', 'Rebuilding Trust Conversation Guide', 'couples'::resource_kind, 'A guide for partners to talk about trust after substance use has strained the relationship.', 'Use it to help partners talk about trust without blame.', array['Couples']::text[], 'Full session', 'Set ground rules first: one speaks, one listens, either can pause. The partner who used substances says what they are doing to rebuild trust; the other says what they need to see. Avoid demands for details. Plan one trust-building action each week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I am doing to rebuild trust"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need to see"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I need from you"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I can offer"}, {"id": "f4", "type": "textarea", "label": "One action we agree on this week"}]'::jsonb, array['addiction', 'support', 'couples']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('anger-early-warning-body-map', 'Anger Early Warning Body Map', 'dbt'::resource_kind, 'A body map where a client marks where anger shows up first and what they can do at the first sign.', 'Use it to help a client catch anger early.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw an outline and mark the body signs of anger from first to last. Then pair each early sign with a small skill: a pause, a drink of water, leaving the room. Practice noticing in session. Anger often hides other feelings; ask what is under it.', '[{"id": "f0", "type": "textarea", "label": "Where I feel anger first"}, {"id": "f1", "type": "textarea", "label": "What it feels like"}, {"id": "f2", "type": "textarea", "label": "What I think when it starts"}, {"id": "f3", "type": "textarea", "label": "A skill I will use at the first sign"}, {"id": "f4", "type": "textarea", "label": "What I might be feeling underneath"}]'::jsonb, array['anger management', 'regulation', 'skills']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('cool-down-volcano-craft', 'Cool-Down Volcano Craft', 'kids'::resource_kind, 'A craft where a child builds a paper volcano and lists calm-down moves for each level.', 'Use it to give a child a picture for anger and ways to cool down.', array['Children']::text[], '30 minutes', 'Draw a volcano with three levels: simmering, bubbling, erupting. The child writes or draws cool-down moves at each level. The parent practices one move with the child. Anger is normal; the work is about what we do with it.', '[{"id": "f0", "type": "textarea", "label": "Draw my volcano"}, {"id": "f1", "type": "textarea", "label": "What makes me simmer"}, {"id": "f2", "type": "textarea", "label": "What my body does when I bubble"}, {"id": "f3", "type": "textarea", "label": "Cool-down moves I will try"}, {"id": "f4", "type": "textarea", "label": "Who can help me cool down"}]'::jsonb, array['anger management', 'art', 'regulation']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('anger-reset-relay-game', 'Anger Reset Relay Game', 'game'::resource_kind, 'A relay where players take a calming step at each station before passing the baton.', 'Use it to help players practice calm-down steps in a lively way.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Set up stations: breathe, stretch, count backward, say a kind sentence. A player does each in turn, rating their calm at the end. Take turns and cheer for effort. Debrief by asking which station helped and where they could use it at home.', '[{"id": "f0", "type": "textarea", "label": "The station I liked best"}, {"id": "f1", "type": "textarea", "label": "How calm I felt, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "When I could use it"}, {"id": "f3", "type": "textarea", "label": "What got in the way"}]'::jsonb, array['anger management', 'play', 'group']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('after-the-anger-look-back-sheet', 'After the Anger Look-Back Sheet', 'cbt'::resource_kind, 'A sheet for looking back at an angry moment, what it cost and how to repair.', 'Use it to help a client reflect on and repair after an angry moment.', array['Adults']::text[], '30 minutes', 'Review a recent moment without lecturing. The client names the trigger, thoughts and actions, then the cost to them and others. End with a repair step, such as an apology or a plan. Safety first: if anyone was hurt, follow your usual duties.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "What I was thinking"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What it cost me and others"}, {"id": "f4", "type": "textarea", "label": "A repair I can make"}, {"id": "f5", "type": "textarea", "label": "What I will try next time"}]'::jsonb, array['anger management', 'repair', 'thinking traps']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('cooling-off-timeout-plan', 'Cooling Off Timeout Plan', 'worksheet'::resource_kind, 'A plan for stepping away from heated moments with a return time and what to do during the break.', 'Use it to help a client use a break skillfully.', array['Adults', 'Couples']::text[], '25 minutes', 'Write the plan with a phrase for leaving, a place to cool down, an activity for the break, and a time to come back. Make clear a break is not avoidance. If a partner is involved, they agree to the plan ahead. Practice the phrase aloud.', '[{"id": "f0", "type": "textarea", "label": "The phrase I will say to call a break"}, {"id": "f1", "type": "textarea", "label": "Where I will go"}, {"id": "f2", "type": "textarea", "label": "What I will do to cool down"}, {"id": "f3", "type": "textarea", "label": "How long I will take"}, {"id": "f4", "type": "textarea", "label": "How I will return to the conversation"}]'::jsonb, array['anger management', 'boundaries', 'skills']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('compulsion-delay-log', 'Compulsion Delay Log', 'cbt'::resource_kind, 'A log for noting an urge to do a compulsion, how long the client delayed it and what happened.', 'Use it to help a client practice delaying compulsions by small steps.', array['Adults']::text[], 'One week', 'Pick one compulsion and agree on a delay the client can manage, such as two minutes. They log the urge, the delay and what the anxiety did. Stay with what happens rather than getting rid of discomfort. Build up gradually with the client leading.', '[{"id": "f0", "type": "textarea", "label": "The urge"}, {"id": "f1", "type": "textarea", "label": "How long I delayed"}, {"id": "f2", "type": "textarea", "label": "What my anxiety did"}, {"id": "f3", "type": "textarea", "label": "What I noticed"}, {"id": "f4", "type": "textarea", "label": "The delay I will try next"}]'::jsonb, array['OCD', 'exposure', 'uncertainty']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('intrusive-thoughts-defusion-cards', 'Intrusive Thoughts Defusion Cards', 'act'::resource_kind, 'Cards for stepping back from intrusive thoughts by naming them as thoughts rather than facts.', 'Use it to help a client change their relationship with intrusive thoughts.', array['Adults', 'Teens']::text[], '25 minutes', 'Write the most common thought, then a few defusion phrases such as I am having the thought that. Practice saying them in session. Normalize that many people have odd thoughts. Avoid asking for reassurance-like answers about what a thought means.', '[{"id": "f0", "type": "textarea", "label": "An intrusive thought"}, {"id": "f1", "type": "textarea", "label": "I am having the thought that"}, {"id": "f2", "type": "textarea", "label": "What my mind tells me to do"}, {"id": "f3", "type": "textarea", "label": "What I want to do instead"}, {"id": "f4", "type": "textarea", "label": "A value I can act on"}]'::jsonb, array['OCD', 'defusion', 'acceptance']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('exposure-ladder-builder', 'Exposure Ladder Builder', 'worksheet'::resource_kind, 'A ladder of situations ranked from mildly to very distressing, built together as a plan for gradual practice.', 'Use it to help a client build a graded exposure plan.', array['Adults']::text[], '30 minutes', 'List feared situations, rate each, and order them. Begin with a rung the client is willing to try. Plan response prevention in advance: what they will not do afterward. Review each week and move at their pace, never faster.', '[{"id": "f0", "type": "textarea", "label": "Situations that bother me"}, {"id": "f1", "type": "textarea", "label": "Rating of each, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "Where I will start"}, {"id": "f3", "type": "textarea", "label": "What I will not do afterward"}, {"id": "f4", "type": "textarea", "label": "What I will notice"}, {"id": "f5", "type": "textarea", "label": "Who knows my plan"}]'::jsonb, array['OCD', 'exposure', 'avoidance']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('bug-zapper-helper-drawing', 'Bug Zapper Helper Drawing', 'kids'::resource_kind, 'A drawing where a child gives the OCD bug a silly name and draws how they will boss it back.', 'Use it to help a child externalize intrusive worries in a playful way.', array['Children']::text[], '25 minutes', 'Have the child name and draw the pest that bugs them, then draw themselves bossing it back. The parent learns not to join in reassurance or rituals and practices a kind reply instead. Keep it light; the child leads.', '[{"id": "f0", "type": "textarea", "label": "Draw the bug"}, {"id": "f1", "type": "textarea", "label": "Its silly name"}, {"id": "f2", "type": "textarea", "label": "What it tells me to do"}, {"id": "f3", "type": "textarea", "label": "How I will boss it back"}, {"id": "f4", "type": "textarea", "label": "What my parent can say"}]'::jsonb, array['OCD', 'externalizing', 'drawing']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('not-sure-dare-game', 'Not Sure Dare Game', 'game'::resource_kind, 'A game of small dares to tolerate not being sure, with a debrief on what happened.', 'Use it to help players practice sitting with uncertainty.', array['Teens', 'Groups']::text[], '25 minutes', 'Make cards of safe dares such as leaving a note slightly crooked or saying maybe. Players pick a card, do it and rate their discomfort at the start and end. Keep dares comfortable and voluntary. Debrief on what happened versus predictions.', '[{"id": "f0", "type": "textarea", "label": "The dare I chose"}, {"id": "f1", "type": "textarea", "label": "Discomfort before and after"}, {"id": "f2", "type": "textarea", "label": "What I thought would happen"}, {"id": "f3", "type": "textarea", "label": "What did happen"}]'::jsonb, array['OCD', 'uncertainty', 'exposure']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('panic-wave-rating-log', 'Panic Wave Rating Log', 'cbt'::resource_kind, 'A log that tracks how a panic wave rises, peaks and falls, and what the client did while it passed.', 'Use it to help a client see panic as a wave that passes.', array['Adults', 'Teens']::text[], 'One week', 'Have the client log each wave: trigger, body sensations, thoughts, peak rating and how long it lasted. Review for the shape of the wave rather than the cause. Ask what they predicted would happen and what did. Rule out medical concerns through the proper channel.', '[{"id": "f0", "type": "textarea", "label": "Date, time and place"}, {"id": "f1", "type": "textarea", "label": "Body sensations I noticed"}, {"id": "f2", "type": "textarea", "label": "What I feared would happen"}, {"id": "f3", "type": "textarea", "label": "Peak rating, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "How long it lasted"}, {"id": "f5", "type": "textarea", "label": "What I did while it passed"}]'::jsonb, array['panic attacks', 'self-monitoring', 'exposure']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('slow-exhale-rehearsal-card', 'Slow Exhale Rehearsal Card', 'dbt'::resource_kind, 'A card for practicing slow paced breathing when calm so it is ready during a surge.', 'Use it to help a client rehearse a slower breath before they need it.', array['Adults', 'Teens']::text[], '20 minutes', 'Teach a longer exhale than inhale, such as four in and six out, and practice together. Check for any medical reason a client should not hold breath. Practice daily when calm and rate how they feel before and after. Do not promise it will stop panic.', '[{"id": "f0", "type": "textarea", "label": "My breathing count"}, {"id": "f1", "type": "textarea", "label": "When I will practice each day"}, {"id": "f2", "type": "textarea", "label": "How I felt before and after"}, {"id": "f3", "type": "textarea", "label": "What got in the way"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this card"}]'::jsonb, array['panic attacks', 'distress tolerance', 'skills']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('body-sensation-experiment-sheet', 'Body Sensation Experiment Sheet', 'worksheet'::resource_kind, 'A sheet for planning safe exercises that bring on harmless body sensations to learn what they do.', 'Use it to help a client learn that sensations pass without harm.', array['Adults']::text[], '30 minutes', 'Choose one exercise such as spinning in a chair or breathing through a straw, after any medical clearance. The client predicts, tries it with you, then compares. Go at their pace and let them stop. Plan one for practice at home.', '[{"id": "f0", "type": "textarea", "label": "The sensation I fear"}, {"id": "f1", "type": "textarea", "label": "My prediction"}, {"id": "f2", "type": "textarea", "label": "The exercise I tried"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I learned"}, {"id": "f5", "type": "textarea", "label": "The next one I will try"}]'::jsonb, array['panic attacks', 'behavioral experiment', 'exposure']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('panic-helper-cape-drawing', 'Panic Helper Cape Drawing', 'kids'::resource_kind, 'A drawing where a child makes a hero cape with the calm moves they use when their body feels alarmed.', 'Use it to help a child connect big body feelings with calming moves.', array['Children']::text[], '25 minutes', 'Have the child decorate a cape and write calm moves on it: slow breaths, squeezing a pillow, saying it will pass. The parent practices one with them and learns to stay near and calm. Praise effort and keep it playful.', '[{"id": "f0", "type": "textarea", "label": "Draw my hero cape"}, {"id": "f1", "type": "textarea", "label": "My calm moves"}, {"id": "f2", "type": "textarea", "label": "What my body feels when alarmed"}, {"id": "f3", "type": "textarea", "label": "What my parent does to help"}]'::jsonb, array['panic attacks', 'calming', 'art']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('moving-through-panic-values-page', 'Moving Through Panic Values Page', 'act'::resource_kind, 'A page for a client to choose a value-led action even when panic sensations show up.', 'Use it to help a client move toward what matters with sensations present.', array['Adults']::text[], '25 minutes', 'Ask what panic has made the client stop doing, then choose a small step toward it with panic invited along. The aim is not to avoid sensations but to keep moving. Plan an easy first step and review how it went.', '[{"id": "f0", "type": "textarea", "label": "Something panic keeps me from"}, {"id": "f1", "type": "textarea", "label": "Why it matters to me"}, {"id": "f2", "type": "textarea", "label": "A small step I will take"}, {"id": "f3", "type": "textarea", "label": "Sensations I may notice"}, {"id": "f4", "type": "textarea", "label": "How I will keep going with them"}]'::jsonb, array['panic attacks', 'willingness', 'values']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('calm-before-correcting-parent-plan', 'Calm Before Correcting Parent Plan', 'worksheet'::resource_kind, 'A plan for a parent to pause, breathe and respond calmly before correcting a child.', 'Use it to help a parent respond rather than react.', array['Adults']::text[], '25 minutes', 'Ask the parent to name the moments they react fastest, then choose a pause phrase and a calm action. Role-play one scenario. Normalize that parents get stressed. Do not frame this as blame; invite curiosity about what tends to precede reactions.', '[{"id": "f0", "type": "textarea", "label": "Moments when I react fastest"}, {"id": "f1", "type": "textarea", "label": "What I feel in my body"}, {"id": "f2", "type": "textarea", "label": "My pause phrase"}, {"id": "f3", "type": "textarea", "label": "What I will do before I respond"}, {"id": "f4", "type": "textarea", "label": "What I will say to my child"}]'::jsonb, array['parenting', 'regulation', 'skills']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('praise-that-sticks-practice-page', 'Praise That Sticks Practice Page', 'kids'::resource_kind, 'A page where a parent and child practice specific praise and a child records what they did well.', 'Use it to help parents give specific, warm praise.', array['Adults', 'Children']::text[], '20 minutes', 'Model specific praise such as I liked how you waited for your turn. The parent writes three they can give this week; the child draws or says one thing they are proud of. Praise effort, not outcome. Keep it playful, not corrective.', '[{"id": "f0", "type": "textarea", "label": "Three things I can praise this week"}, {"id": "f1", "type": "textarea", "label": "Exactly what I will say"}, {"id": "f2", "type": "textarea", "label": "Draw something I am proud of"}, {"id": "f3", "type": "textarea", "label": "How it felt to hear praise"}]'::jsonb, array['parenting', 'strengths', 'connection']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('co-parenting-agreement-conversation', 'Co-Parenting Agreement Conversation', 'couples'::resource_kind, 'A conversation guide for two caregivers to agree on a few shared routines and responses.', 'Use it to help caregivers align on a few shared expectations.', array['Couples']::text[], 'Full session', 'Pick two or three issues, such as screens or bedtime. Each caregiver says what they want and why. Aim for a small agreement and a plan to review. Avoid trying to settle everything at once. Respect that parents may have different styles.', '[{"id": "f0", "type": "textarea", "label": "Caregiver A: what I want and why"}, {"id": "f1", "type": "textarea", "label": "Caregiver B: what I want and why"}, {"id": "f2", "type": "textarea", "label": "What we agree on"}, {"id": "f3", "type": "textarea", "label": "What we will try for two weeks"}, {"id": "f4", "type": "textarea", "label": "When we will check in"}]'::jsonb, array['parenting', 'communication', 'couples']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('family-rule-charades-game', 'Family Rule Charades Game', 'game'::resource_kind, 'A charades game where family members act out house rules and kind ways to follow them.', 'Use it to help families talk about expectations in a playful way.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Write family rules on cards. Players act them out while others guess, and then say why the rule matters. Parents join in. Debrief by asking which rule is easiest to follow and which could use a tweak.', '[{"id": "f0", "type": "textarea", "label": "A rule I acted out"}, {"id": "f1", "type": "textarea", "label": "Why it matters"}, {"id": "f2", "type": "textarea", "label": "One rule that is hard"}, {"id": "f3", "type": "textarea", "label": "What would help me follow it"}]'::jsonb, array['parenting', 'family', 'play']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('parent-self-care-anchor-dbt-page', 'Parent Self-Care Anchor DBT Page', 'dbt'::resource_kind, 'A page where a parent chooses small self-care anchors and a skill for the hardest part of the day.', 'Use it to help a parent protect small moments for themselves.', array['Adults']::text[], '25 minutes', 'Identify the hardest hour of the parent''s day and one skill, such as paced breathing or a cold splash. Add a tiny self-care anchor that fits the week. Reassure them that caring for themselves is part of caring for their child.', '[{"id": "f0", "type": "textarea", "label": "The hardest part of my day"}, {"id": "f1", "type": "textarea", "label": "A skill I will use there"}, {"id": "f2", "type": "textarea", "label": "A tiny self-care anchor"}, {"id": "f3", "type": "textarea", "label": "When I will do it"}, {"id": "f4", "type": "textarea", "label": "Who can cover for me"}]'::jsonb, array['parenting', 'self-compassion', 'distress tolerance']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('protected-sleep-shifts-for-new-parents', 'Protected Sleep Shifts for New Parents', 'worksheet'::resource_kind, 'A plan for sharing night duties and protecting stretches of sleep in the first months.', 'Use it to help new parents protect sleep together.', array['Adults', 'Couples']::text[], '30 minutes', 'Map the night and divide shifts so each parent gets one longer stretch. Ask about help from family or friends. Sleep loss can make everything harder; if the client reports thoughts of self-harm, follow your usual steps and share 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "Our current night routine"}, {"id": "f1", "type": "textarea", "label": "Shifts that could protect a longer sleep"}, {"id": "f2", "type": "textarea", "label": "Help we could ask for"}, {"id": "f3", "type": "textarea", "label": "What I will do on a bad night"}, {"id": "f4", "type": "textarea", "label": "Support line any time: 988 (call or text)"}]'::jsonb, array['perinatal and postpartum', 'sleep', 'support']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('expectations-and-reality-reframe-sheet', 'Expectations and Reality Reframe Sheet', 'cbt'::resource_kind, 'A sheet for comparing the picture of early parenthood a client expected with what is happening, kindly.', 'Use it to help a client soften unfair standards in early parenthood.', array['Adults']::text[], '25 minutes', 'Ask what the client thought this time would be like and what it is like. Explore should statements and build kinder versions. Avoid cheerleading; allow disappointment. Pay attention to comments about hopelessness and follow your usual steps.', '[{"id": "f0", "type": "textarea", "label": "What I thought it would be like"}, {"id": "f1", "type": "textarea", "label": "What it is like"}, {"id": "f2", "type": "textarea", "label": "The shoulds I hold"}, {"id": "f3", "type": "textarea", "label": "A kinder version"}, {"id": "f4", "type": "textarea", "label": "One thing that is good enough today"}]'::jsonb, array['perinatal and postpartum', 'thinking traps', 'self-compassion']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('partner-handoff-check-in', 'Partner Handoff Check-In', 'couples'::resource_kind, 'A short check-in for partners to hand off the day, share feelings and divide the evening.', 'Use it to help partners support each other through the early months.', array['Couples']::text[], '20 minutes', 'Partners take turns saying how the day went and what they need for the evening, then divide tasks. Keep it brief. Encourage appreciation. If either partner is struggling more than expected, talk about support options and follow your usual steps.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my day and what I need"}, {"id": "f1", "type": "textarea", "label": "Partner B: my day and what I need"}, {"id": "f2", "type": "textarea", "label": "How we will split tonight"}, {"id": "f3", "type": "textarea", "label": "One thing I appreciate"}, {"id": "f4", "type": "textarea", "label": "When we will do this again"}]'::jsonb, array['perinatal and postpartum', 'communication', 'couples']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('values-after-baby-page', 'Values After Baby Page', 'act'::resource_kind, 'A page for exploring what matters now and tiny ways to live it during a season of high demands.', 'Use it to help a client stay connected to values during early parenthood.', array['Adults']::text[], '25 minutes', 'Ask what matters most in this season and what has had to pause. Find a tiny way to honor each value this week, such as ten minutes outside. Validate loss as well as joy. Keep the actions very small.', '[{"id": "f0", "type": "textarea", "label": "What matters most right now"}, {"id": "f1", "type": "textarea", "label": "What I miss"}, {"id": "f2", "type": "textarea", "label": "A tiny way to honor it"}, {"id": "f3", "type": "textarea", "label": "What may get in the way"}, {"id": "f4", "type": "textarea", "label": "Who can help"}]'::jsonb, array['perinatal and postpartum', 'values', 'committed action']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('calm-breath-for-the-baby-hours-card', 'Calm Breath for the Baby Hours Card', 'dbt'::resource_kind, 'A card for using a skill during the hardest hours, such as a crying spell, with a plan to hand off.', 'Use it to give a parent a skill and an exit plan for hard moments.', array['Adults']::text[], '20 minutes', 'Choose a skill such as paced breathing or a cold splash and a safe plan: put the baby down in a safe place and step away for a moment, or hand off to someone. Normalize needing a break. If a client feels they could harm themselves or the baby, follow your usual steps and name 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "The hardest moments of the day"}, {"id": "f1", "type": "textarea", "label": "My skill"}, {"id": "f2", "type": "textarea", "label": "Where I can safely put the baby down"}, {"id": "f3", "type": "textarea", "label": "Who I can call for a handoff"}, {"id": "f4", "type": "textarea", "label": "988 (call or text) any time"}]'::jsonb, array['perinatal and postpartum', 'distress tolerance', 'safety']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('compliment-collection-page', 'Compliment Collection Page', 'cbt'::resource_kind, 'A page where a client records compliments and examines what they say about them.', 'Use it to help a client take in positive feedback instead of dismissing it.', array['Adults', 'Teens']::text[], 'One week', 'Ask the client to note each compliment and their automatic reply, then write what they could say instead. Clients often discount it; explore what they would say if a friend got it. Review the collection together.', '[{"id": "f0", "type": "textarea", "label": "The compliment"}, {"id": "f1", "type": "textarea", "label": "My automatic reply"}, {"id": "f2", "type": "textarea", "label": "What it says about me"}, {"id": "f3", "type": "textarea", "label": "A simple way to say thank you"}, {"id": "f4", "type": "textarea", "label": "How I felt"}]'::jsonb, array['self-esteem', 'automatic thoughts', 'strengths']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('self-worth-values-anchor', 'Self-Worth Values Anchor', 'act'::resource_kind, 'A page that links a client''s sense of worth to who they choose to be rather than performance.', 'Use it to help a client ground self-worth in values.', array['Adults']::text[], '25 minutes', 'Ask what the client wants to be known for, then look at recent times they acted on it regardless of results. Compare this with the performance standard they usually apply. Keep it concrete, with one example per value.', '[{"id": "f0", "type": "textarea", "label": "How I judge myself most days"}, {"id": "f1", "type": "textarea", "label": "What I want to be known for"}, {"id": "f2", "type": "textarea", "label": "A recent time I acted on that"}, {"id": "f3", "type": "textarea", "label": "What this says about my worth"}, {"id": "f4", "type": "textarea", "label": "One action this week"}]'::jsonb, array['self-esteem', 'values', 'self-compassion']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('things-i-like-about-me-poster', 'Things I Like About Me Poster', 'kids'::resource_kind, 'A poster where a child draws and writes what they like about themselves, their family and their day.', 'Use it to help a child build a picture of who they are.', array['Children']::text[], '30 minutes', 'Hand out paper and markers and ask the child to fill it with things they like, are good at and love. The parent adds one note and helps hang it. Praise honesty, not perfection. Keep comparison out of it.', '[{"id": "f0", "type": "textarea", "label": "Draw me"}, {"id": "f1", "type": "textarea", "label": "Things I like about me"}, {"id": "f2", "type": "textarea", "label": "Things I am good at"}, {"id": "f3", "type": "textarea", "label": "People who love me"}]'::jsonb, array['self-esteem', 'strengths', 'art']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('strengths-spotlight-game', 'Strengths Spotlight Game', 'game'::resource_kind, 'A game where players take turns being in the spotlight while others name real strengths they have seen.', 'Use it to help group members hear specific strengths from others.', array['Teens', 'Groups']::text[], '25 minutes', 'Set kind ground rules and a time limit. Each player takes a turn in the spotlight while others name strengths with examples. The spotlighted player says thank you and writes down one. Debrief on what was hard to hear.', '[{"id": "f0", "type": "textarea", "label": "Strengths people named"}, {"id": "f1", "type": "textarea", "label": "The one that surprised me"}, {"id": "f2", "type": "textarea", "label": "What I want to remember"}, {"id": "f3", "type": "textarea", "label": "What it was like to be in the spotlight"}]'::jsonb, array['self-esteem', 'strengths', 'group']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('good-enough-standards-worksheet', 'Good Enough Standards Worksheet', 'worksheet'::resource_kind, 'A worksheet comparing a client''s usual standard to a good-enough version across areas of life.', 'Use it to help a client loosen perfectionism and keep what works.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick two areas where the client holds a high standard. Compare what the standard costs with what a good-enough version would look like. Test one good-enough choice this week. Do not push them to lower standards everywhere.', '[{"id": "f0", "type": "textarea", "label": "An area where my standard is very high"}, {"id": "f1", "type": "textarea", "label": "What it costs me"}, {"id": "f2", "type": "textarea", "label": "A good-enough version"}, {"id": "f3", "type": "textarea", "label": "What I fear might happen"}, {"id": "f4", "type": "textarea", "label": "My plan to test it"}]'::jsonb, array['self-esteem', 'perfectionism', 'planning']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('attention-shift-experiment', 'Attention Shift Experiment', 'cbt'::resource_kind, 'An experiment comparing attention on self with attention on the conversation and the room.', 'Use it to help a client see how self-focus affects their experience.', array['Adults', 'Teens']::text[], '30 minutes', 'In session, have the client talk with you once while watching themselves, and once while focusing on you and the room. Compare how each felt. Plan to try it in a low-stakes setting. This is exploratory; the client decides what it means.', '[{"id": "f0", "type": "textarea", "label": "How it felt focusing on myself"}, {"id": "f1", "type": "textarea", "label": "How it felt focusing on the room"}, {"id": "f2", "type": "textarea", "label": "What I noticed in the other person"}, {"id": "f3", "type": "textarea", "label": "Where I will try this"}, {"id": "f4", "type": "textarea", "label": "What I predict"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'self-monitoring']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('conversation-openers-card-game', 'Conversation Openers Card Game', 'game'::resource_kind, 'A card game of low-stakes conversation starters players practice in pairs.', 'Use it to help players practice small talk in a safe setting.', array['Teens', 'Groups']::text[], '25 minutes', 'Make cards with simple openers such as What was the best part of your week. Pairs draw, ask and answer, then rate how it felt. Rotate partners. Debrief on what made it easier and which openers they might use.', '[{"id": "f0", "type": "textarea", "label": "The opener I liked"}, {"id": "f1", "type": "textarea", "label": "How it felt to ask"}, {"id": "f2", "type": "textarea", "label": "How it felt to answer"}, {"id": "f3", "type": "textarea", "label": "One I will use this week"}]'::jsonb, array['social anxiety', 'communication', 'group']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('social-life-values-compass', 'Social Life Values Compass', 'act'::resource_kind, 'A compass pointing toward the kind of friend or colleague a client wants to be, even with nerves along.', 'Use it to help a client act on social values while anxious.', array['Adults']::text[], '25 minutes', 'Ask what kind of presence the client wants in social settings and what small act would show it. Plan one and expect nerves to come. The action is the goal, not feeling at ease. Review what happened without grading it.', '[{"id": "f0", "type": "textarea", "label": "The kind of friend I want to be"}, {"id": "f1", "type": "textarea", "label": "A small action that shows it"}, {"id": "f2", "type": "textarea", "label": "Nerves I expect"}, {"id": "f3", "type": "textarea", "label": "How I will carry them along"}, {"id": "f4", "type": "textarea", "label": "Who I will try it with"}]'::jsonb, array['social anxiety', 'values', 'willingness']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('embarrassment-tolerance-practice-plan', 'Embarrassment Tolerance Practice Plan', 'dbt'::resource_kind, 'A plan for practicing small, safe awkward moments and using skills to ride out the feeling.', 'Use it to help a client practice tolerating embarrassment.', array['Adults', 'Teens']::text[], '30 minutes', 'Choose a small, harmless awkward act, such as asking a store worker a simple question. The client plans a skill, tries it, and rates embarrassment before and after. Keep steps small and voluntary.', '[{"id": "f0", "type": "textarea", "label": "The small awkward act"}, {"id": "f1", "type": "textarea", "label": "A skill I will use"}, {"id": "f2", "type": "textarea", "label": "Embarrassment before and after"}, {"id": "f3", "type": "textarea", "label": "What happened"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['social anxiety', 'distress tolerance', 'exposure']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('brave-hello-practice-drawing', 'Brave Hello Practice Drawing', 'kids'::resource_kind, 'A drawing of a brave hello with speech bubbles a child practices with a parent.', 'Use it to help a child rehearse greetings and small interactions.', array['Children']::text[], '25 minutes', 'Have the child draw two people meeting and fill the speech bubbles. Role-play the hello with the parent. The parent offers calm support and does not speak for the child. Celebrate trying.', '[{"id": "f0", "type": "textarea", "label": "Draw my brave hello"}, {"id": "f1", "type": "textarea", "label": "What I will say"}, {"id": "f2", "type": "textarea", "label": "What they might say"}, {"id": "f3", "type": "textarea", "label": "Who I will say hello to"}]'::jsonb, array['social anxiety', 'courage', 'children']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('grief-waves-comfort-plan', 'Grief Waves Comfort Plan', 'worksheet'::resource_kind, 'A plan listing what helps when a wave of grief arrives and who can be called on.', 'Use it to give a client a short plan for waves of grief.', array['Adults']::text[], '25 minutes', 'Ask the client when waves tend to come and what they need then. List comfort items and people, and one thing to do afterward. Grief is not a problem to solve. If the client mentions thoughts of ending their life, follow your usual steps and name 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "When the waves tend to come"}, {"id": "f1", "type": "textarea", "label": "What helps in the moment"}, {"id": "f2", "type": "textarea", "label": "Who I can reach out to"}, {"id": "f3", "type": "textarea", "label": "Something kind I can do afterward"}, {"id": "f4", "type": "textarea", "label": "988 (call or text) any time"}]'::jsonb, array['grief and loss', 'support', 'coping skills']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('memory-box-craft-for-children', 'Memory Box Craft for Children', 'kids'::resource_kind, 'A craft where a child decorates a box and fills it with drawings and keepsakes of someone they miss.', 'Use it to help a child hold memories of someone they have lost.', array['Children']::text[], '30 minutes', 'Provide a box and art supplies. The child decorates it and chooses items to put in. The parent shares one memory. Follow the child''s lead about talking. Children grieve in bursts; let play and sadness both be there.', '[{"id": "f0", "type": "textarea", "label": "Draw something I remember"}, {"id": "f1", "type": "textarea", "label": "What I would tell them"}, {"id": "f2", "type": "textarea", "label": "Something I put in my box"}, {"id": "f3", "type": "textarea", "label": "Who I can share a memory with"}]'::jsonb, array['grief and loss', 'art', 'family']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('continuing-bonds-ritual-planner', 'Continuing Bonds Ritual Planner', 'act'::resource_kind, 'A planner for a small ritual that keeps a client connected to someone they lost.', 'Use it to help a client honor a relationship that continues in memory.', array['Adults']::text[], '30 minutes', 'Ask what the person valued and how the client might carry it. Choose a ritual such as cooking a favorite dish. Grief and value live side by side; allow both feelings. Offer to adjust the ritual as grief changes.', '[{"id": "f0", "type": "textarea", "label": "Who I am remembering"}, {"id": "f1", "type": "textarea", "label": "What mattered to them"}, {"id": "f2", "type": "textarea", "label": "A way I can carry it forward"}, {"id": "f3", "type": "textarea", "label": "When I will do my ritual"}, {"id": "f4", "type": "textarea", "label": "What I may feel and how I will let it be"}]'::jsonb, array['grief and loss', 'values', 'acceptance']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('shared-grief-conversation-for-partners', 'Shared Grief Conversation for Partners', 'couples'::resource_kind, 'A guide for partners to talk about how each grieves and what each needs.', 'Use it to help partners support each other in different styles of grief.', array['Couples']::text[], '30 minutes', 'Each partner describes how they grieve and what they need. Find one ritual to share and one thing each does alone. Avoid ranking grief. If either mentions thoughts of ending their life, follow your usual steps and name 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I grieve"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I grieve"}, {"id": "f2", "type": "textarea", "label": "What I need from you"}, {"id": "f3", "type": "textarea", "label": "One ritual we can share"}, {"id": "f4", "type": "textarea", "label": "What each of us does alone"}]'::jsonb, array['grief and loss', 'understanding', 'couples']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('memory-circle-game', 'Memory Circle Game', 'game'::resource_kind, 'A group game where players share a memory, a quality or a thing they miss about someone.', 'Use it to help a group share memories of people they have lost.', array['Teens', 'Groups']::text[], '30 minutes', 'Set a gentle tone and a pass rule. Players take turns drawing a prompt such as A thing they loved to do. Others listen. Debrief with a closing breath. Watch for strong distress and offer a break or follow-up.', '[{"id": "f0", "type": "textarea", "label": "The prompt I drew"}, {"id": "f1", "type": "textarea", "label": "What I shared"}, {"id": "f2", "type": "textarea", "label": "What I heard from others"}, {"id": "f3", "type": "textarea", "label": "What I need after this"}]'::jsonb, array['grief and loss', 'group', 'support']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('relationship-needs-and-boundaries-sort', 'Relationship Needs and Boundaries Sort', 'cbt'::resource_kind, 'A sort of needs and boundaries a client holds in a relationship, with what to ask for and what to protect.', 'Use it to help a client name needs and boundaries clearly.', array['Adults']::text[], '30 minutes', 'Ask the client to list needs, then mark which are met, partly met or unmet. Pick one to ask for. Practice wording. If safety is a concern in the relationship, follow your usual steps, including safety planning, before any joint work.', '[{"id": "f0", "type": "textarea", "label": "Needs I have in this relationship"}, {"id": "f1", "type": "textarea", "label": "Which are met"}, {"id": "f2", "type": "textarea", "label": "Which are not"}, {"id": "f3", "type": "textarea", "label": "One boundary I want to keep"}, {"id": "f4", "type": "textarea", "label": "How I will say it"}]'::jsonb, array['relationship issues', 'boundaries', 'communication']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('dear-man-script-planner', 'DEAR MAN Script Planner', 'dbt'::resource_kind, 'A planner for scripting a request or a no using describe, express, assert, reinforce and the rest.', 'Use it to help a client plan an effective request.', array['Adults', 'Teens']::text[], '30 minutes', 'Write each step for one real request and rehearse aloud. Clients often skip describe and reinforce; point them out. Adjust for the person and setting. The goal is skillful asking, not winning.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "Describe the facts"}, {"id": "f2", "type": "textarea", "label": "Express how I feel"}, {"id": "f3", "type": "textarea", "label": "Assert what I want"}, {"id": "f4", "type": "textarea", "label": "Reinforce why it helps"}, {"id": "f5", "type": "textarea", "label": "My opening line"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'DEAR MAN']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('hurt-underneath-anger-conversation', 'Hurt Underneath Anger Conversation', 'couples'::resource_kind, 'A guide for partners to say the hurt underneath their anger and hear each other''s.', 'Use it to help partners speak from hurt instead of attack.', array['Couples']::text[], 'Full session', 'Each partner finishes a prompt about a recent argument: when this happened I felt hurt because. The other reflects it back before replying. Stop if either is flooded. The goal is understanding.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what happened"}, {"id": "f1", "type": "textarea", "label": "Partner A: the hurt underneath"}, {"id": "f2", "type": "textarea", "label": "Partner B: what happened"}, {"id": "f3", "type": "textarea", "label": "Partner B: the hurt underneath"}, {"id": "f4", "type": "textarea", "label": "Something we can each do differently"}]'::jsonb, array['relationship issues', 'conflict', 'understanding']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('compliment-swap-game', 'Compliment Swap Game', 'game'::resource_kind, 'A game where partners or friends trade specific compliments and say what they mean.', 'Use it to help pairs practice warm, specific appreciation.', array['Couples', 'Groups']::text[], '20 minutes', 'Players take turns giving a specific compliment with an example. The receiver says thanks and repeats it. Rotate partners if in a group. Debrief by asking which one landed best and why.', '[{"id": "f0", "type": "textarea", "label": "A compliment I gave"}, {"id": "f1", "type": "textarea", "label": "One I received"}, {"id": "f2", "type": "textarea", "label": "Why it landed"}, {"id": "f3", "type": "textarea", "label": "One I want to give this week"}]'::jsonb, array['relationship issues', 'connection', 'play']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('relationship-patterns-timeline', 'Relationship Patterns Timeline', 'worksheet'::resource_kind, 'A timeline for noticing patterns across relationships, such as how closeness, conflict and distance repeat.', 'Use it to help a client see patterns without blame.', array['Adults']::text[], '30 minutes', 'Map key relationships and what repeated. Ask what the client wants to keep and what to try differently. Stay with patterns and choices, not fault. If past abuse emerges, slow down and prioritize safety and support.', '[{"id": "f0", "type": "textarea", "label": "Relationships on my timeline"}, {"id": "f1", "type": "textarea", "label": "What repeated"}, {"id": "f2", "type": "textarea", "label": "What I am proud of"}, {"id": "f3", "type": "textarea", "label": "What I want to try differently"}, {"id": "f4", "type": "textarea", "label": "A small step I can take"}]'::jsonb, array['relationship issues', 'reflection', 'planning']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('safe-people-and-places-map', 'Safe People and Places Map', 'worksheet'::resource_kind, 'A map of people, places and activities that feel safe, to build a sense of support without retelling events.', 'Use it to help a client strengthen safety and support.', array['Adults', 'Teens']::text[], '25 minutes', 'Stay with the present: who is safe now, where feels safe, what helps. Do not ask for details of what happened, and never assign it as homework. Let the client set the pace. Review safety needs each session.', '[{"id": "f0", "type": "textarea", "label": "People I feel safe with"}, {"id": "f1", "type": "textarea", "label": "Places that feel safe"}, {"id": "f2", "type": "textarea", "label": "Things that help me feel steady"}, {"id": "f3", "type": "textarea", "label": "Someone I can tell if I need help"}, {"id": "f4", "type": "textarea", "label": "A small thing I can do for myself today"}]'::jsonb, array['sexual abuse', 'safety', 'support']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('pacing-and-stop-signal-plan', 'Pacing and Stop Signal Plan', 'dbt'::resource_kind, 'A plan for how a client can slow down or stop in session, with a signal and a grounding skill.', 'Use it to help a client feel in control of pace in therapy.', array['Adults']::text[], '20 minutes', 'Agree on a signal to pause, a skill to use, and a check-in rule. Practice using it on something neutral. Reinforce that the client decides how fast to go. Never ask for written details of what happened as homework.', '[{"id": "f0", "type": "textarea", "label": "My stop signal"}, {"id": "f1", "type": "textarea", "label": "A grounding skill I will use"}, {"id": "f2", "type": "textarea", "label": "How I want you to check in"}, {"id": "f3", "type": "textarea", "label": "What helps after a hard session"}, {"id": "f4", "type": "textarea", "label": "Who I can contact between sessions"}]'::jsonb, array['sexual abuse', 'pacing', 'grounding']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('reclaiming-choice-values-page', 'Reclaiming Choice Values Page', 'act'::resource_kind, 'A page to choose small, safe actions that reflect what the client values now.', 'Use it to help a client rebuild a sense of choice and direction.', array['Adults']::text[], '30 minutes', 'Invite the client to pick small daily choices, such as what to eat or when to rest, that reflect their values. Focus on the present. Do not explore details of what happened. Celebrate every choice as theirs.', '[{"id": "f0", "type": "textarea", "label": "Something I value"}, {"id": "f1", "type": "textarea", "label": "A small choice I can make today"}, {"id": "f2", "type": "textarea", "label": "How it feels to choose"}, {"id": "f3", "type": "textarea", "label": "What supports me"}, {"id": "f4", "type": "textarea", "label": "What I might choose next"}]'::jsonb, array['sexual abuse', 'values', 'safety']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('my-safe-hand-helpers-drawing', 'My Safe Hand Helpers Drawing', 'kids'::resource_kind, 'A drawing where a child traces a hand and writes a safe grown-up on each finger.', 'Use it to help a child name trusted people to tell if something feels wrong.', array['Children']::text[], '25 minutes', 'Trace the child''s hand and write or draw a safe person on each finger. The parent learns who the child names. Remind yourself of your reporting duties if a child discloses, and respond calmly: you are believed and not in trouble. Never press for details.', '[{"id": "f0", "type": "textarea", "label": "Draw around my hand"}, {"id": "f1", "type": "textarea", "label": "Safe people on my fingers"}, {"id": "f2", "type": "textarea", "label": "What I can say if something feels wrong"}, {"id": "f3", "type": "textarea", "label": "Who will help me"}]'::jsonb, array['sexual abuse', 'safety', 'drawing']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('safety-cards-calm-game', 'Safety Cards Calm Game', 'game'::resource_kind, 'A game of cards with grounding and safety skills that players draw and try.', 'Use it to help a group practice grounding and safety skills.', array['Teens', 'Groups']::text[], '25 minutes', 'Make cards with skills such as feel your feet, name five blues, call a trusted person. Players draw, try, and rate steadiness. Passing is always okay. Do not ask for stories; keep to skills.', '[{"id": "f0", "type": "textarea", "label": "The skill I drew"}, {"id": "f1", "type": "textarea", "label": "How steady I felt after"}, {"id": "f2", "type": "textarea", "label": "A skill I might use this week"}, {"id": "f3", "type": "textarea", "label": "Who I can ask for help"}]'::jsonb, array['sexual abuse', 'grounding', 'group']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('coping-skills-by-situation-matrix', 'Coping Skills by Situation Matrix', 'dbt'::resource_kind, 'A matrix matching coping skills with situations, such as at work or at night.', 'Use it to help a client match skills to where they are needed.', array['Adults', 'Teens']::text[], '30 minutes', 'List the client''s hard situations and pick one or two skills for each. Practice one in session. Revisit what worked and replace what did not. Skills are tools, not rules.', '[{"id": "f0", "type": "textarea", "label": "Hard situations I face"}, {"id": "f1", "type": "textarea", "label": "A skill for each"}, {"id": "f2", "type": "textarea", "label": "What I need to have ready"}, {"id": "f3", "type": "textarea", "label": "Which I will practice first"}, {"id": "f4", "type": "textarea", "label": "How I will tell if it helped"}]'::jsonb, array['coping skills', 'skills', 'distress tolerance']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('coping-toolbox-decorating-craft', 'Coping Toolbox Decorating Craft', 'kids'::resource_kind, 'A craft where a child decorates a toolbox and fills it with cards of coping ideas.', 'Use it to give a child a physical box of coping choices.', array['Children']::text[], '30 minutes', 'Decorate a box and write or draw coping ideas on cards: breathing, drawing, squeezing a ball, asking for a hug. The parent adds a few and learns when to offer them. Let the child choose.', '[{"id": "f0", "type": "textarea", "label": "Draw my toolbox"}, {"id": "f1", "type": "textarea", "label": "Ideas for my cards"}, {"id": "f2", "type": "textarea", "label": "Which one I will try first"}, {"id": "f3", "type": "textarea", "label": "Who can help me use it"}]'::jsonb, array['coping skills', 'regulation', 'art']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('coping-cards-draw-and-do-game-2', 'Coping Cards Draw and Do Game', 'game'::resource_kind, 'A game of drawing a coping card and trying it for a minute.', 'Use it to help players try different coping skills in a playful way.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Make a deck of coping ideas. Players draw one, do it for a minute and rate their steadiness. Take turns and let anyone pass. Debrief on which skills they would use again.', '[{"id": "f0", "type": "textarea", "label": "The card I drew"}, {"id": "f1", "type": "textarea", "label": "How I felt after"}, {"id": "f2", "type": "textarea", "label": "One I want to use again"}, {"id": "f3", "type": "textarea", "label": "What got in the way"}]'::jsonb, array['coping skills', 'play', 'group']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('coping-skills-effectiveness-log', 'Coping Skills Effectiveness Log', 'worksheet'::resource_kind, 'A log noting which skills the client used, how long, and how much they helped.', 'Use it to help a client learn which skills help them most.', array['Adults', 'Teens']::text[], 'One week', 'The client records the situation, the skill, and a rating of distress before and after. Review at the next session for what to keep and what to drop. Avoid judging skills that did not help; look for a better fit.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "The skill I used"}, {"id": "f2", "type": "textarea", "label": "Distress before and after"}, {"id": "f3", "type": "textarea", "label": "What I noticed"}, {"id": "f4", "type": "textarea", "label": "What I will keep"}]'::jsonb, array['coping skills', 'self-monitoring', 'skills']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('pause-and-choose-decision-sheet', 'Pause and Choose Decision Sheet', 'cbt'::resource_kind, 'A sheet for pausing when upset, naming the urge and choosing between a quick relief and a longer-term helpful move.', 'Use it to help a client slow down and choose how to cope.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through a recent upset: the urge, the quick relief, the longer-term cost, the alternative. Role-play choosing the alternative. Clients may feel judged for coping; stay curious about what the quick relief gives them.', '[{"id": "f0", "type": "textarea", "label": "What upset me"}, {"id": "f1", "type": "textarea", "label": "The urge I felt"}, {"id": "f2", "type": "textarea", "label": "A quick relief and its cost"}, {"id": "f3", "type": "textarea", "label": "A helpful alternative"}, {"id": "f4", "type": "textarea", "label": "What I will try next time"}]'::jsonb, array['coping skills', 'problem solving', 'urges']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('fear-ladder-with-safety-behaviors-check', 'Fear Ladder With Safety Behaviors Check', 'cbt'::resource_kind, 'A ladder of feared situations with a column naming safety behaviors the client plans to drop.', 'Use it to help a client plan gradual practice without crutches.', array['Adults', 'Teens']::text[], '30 minutes', 'List situations from least to most feared, then note safety behaviors for each. Choose a first rung and a plan to practice it with fewer crutches. Go gradually and let the client lead. Review after each practice.', '[{"id": "f0", "type": "textarea", "label": "The feared situation"}, {"id": "f1", "type": "textarea", "label": "Steps from easy to hard"}, {"id": "f2", "type": "textarea", "label": "Safety behaviors I use"}, {"id": "f3", "type": "textarea", "label": "The first step I will try"}, {"id": "f4", "type": "textarea", "label": "How I will know I did it"}]'::jsonb, array['phobias', 'exposure', 'avoidance']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('brave-explorer-fear-map-drawing', 'Brave Explorer Fear Map Drawing', 'kids'::resource_kind, 'A drawing where a child maps a feared thing from far away to up close and takes small brave steps.', 'Use it to help a child approach a feared thing step by step.', array['Children']::text[], '30 minutes', 'The child draws a path with stops from far away to close to the feared thing. They choose the first stop and the parent cheers. Take only steps the child is ready for. End each visit on a success.', '[{"id": "f0", "type": "textarea", "label": "Draw my map"}, {"id": "f1", "type": "textarea", "label": "The feared thing"}, {"id": "f2", "type": "textarea", "label": "The first brave stop"}, {"id": "f3", "type": "textarea", "label": "Who goes with me"}, {"id": "f4", "type": "textarea", "label": "How it felt"}]'::jsonb, array['phobias', 'exposure', 'drawing']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('fear-facing-bingo-game', 'Fear Facing Bingo Game', 'game'::resource_kind, 'A bingo game where each square is a small brave step and players mark the ones they try.', 'Use it to help players try small steps toward feared things.', array['Children', 'Teens', 'Groups']::text[], 'Several weeks', 'Make a card of small brave steps with the player. Mark each one done and celebrate with a small reward. Players choose which step; no pressure. Debrief on how each step felt.', '[{"id": "f0", "type": "textarea", "label": "The steps on my card"}, {"id": "f1", "type": "textarea", "label": "The one I tried"}, {"id": "f2", "type": "textarea", "label": "How it felt"}, {"id": "f3", "type": "textarea", "label": "The next one"}]'::jsonb, array['phobias', 'courage', 'play']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('willing-to-be-afraid-values-page', 'Willing to Be Afraid Values Page', 'act'::resource_kind, 'A page connecting a feared thing to what the client misses out on and what they would do if they were willing.', 'Use it to help a client choose to feel fear and move toward a value.', array['Adults']::text[], '25 minutes', 'Ask what the fear has kept the client from, and what they would do if fear were along for the ride. Choose a step. Expect fear to show up. The task is acting, not eliminating fear.', '[{"id": "f0", "type": "textarea", "label": "What fear keeps me from"}, {"id": "f1", "type": "textarea", "label": "Why it matters to me"}, {"id": "f2", "type": "textarea", "label": "A step I would take"}, {"id": "f3", "type": "textarea", "label": "What fear may say"}, {"id": "f4", "type": "textarea", "label": "How I will keep going"}]'::jsonb, array['phobias', 'values', 'willingness']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('fear-rating-during-practice-log', 'Fear Rating During Practice Log', 'worksheet'::resource_kind, 'A log of fear ratings during and after exposure practice to see how fear rises and falls.', 'Use it to help a client track fear during practice.', array['Adults', 'Teens']::text[], 'One week', 'Have the client rate fear before, during and after each practice. Review the pattern. Practice repeated often matters more than perfect. Adjust the next step to stay challenging but doable.', '[{"id": "f0", "type": "textarea", "label": "The practice"}, {"id": "f1", "type": "textarea", "label": "Fear before"}, {"id": "f2", "type": "textarea", "label": "Fear at the peak"}, {"id": "f3", "type": "textarea", "label": "Fear after"}, {"id": "f4", "type": "textarea", "label": "What I noticed"}, {"id": "f5", "type": "textarea", "label": "What I will do next"}]'::jsonb, array['phobias', 'self-monitoring', 'exposure']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('body-thank-you-function-list', 'Body Thank-You Function List', 'act'::resource_kind, 'A list of what a client''s body does for them, from carrying groceries to hugging someone.', 'Use it to help a client shift attention from looks to what the body does.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask for a list of functions: what the body lets the client do, feel and share. Avoid any talk about size, shape or measurement. Add one thing to the list each day. Gently redirect appearance talk back to function and values.', '[{"id": "f0", "type": "textarea", "label": "Things my body lets me do"}, {"id": "f1", "type": "textarea", "label": "Ways it helps me connect with others"}, {"id": "f2", "type": "textarea", "label": "A moment I was glad to be in it"}, {"id": "f3", "type": "textarea", "label": "One thing I can thank it for today"}]'::jsonb, array['body image', 'gratitude', 'values']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('mirror-talk-reframe-page', 'Mirror Talk Reframe Page', 'cbt'::resource_kind, 'A page for noticing harsh self-talk about appearance and writing a kinder, more neutral statement.', 'Use it to help a client reshape appearance-related self-talk.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for the thoughts the client has when looking in a mirror and what they predict others think. Build neutral or kind statements. Never discuss weight, shape or food. Practice the new statement aloud.', '[{"id": "f0", "type": "textarea", "label": "The thought I have in the mirror"}, {"id": "f1", "type": "textarea", "label": "What it makes me do"}, {"id": "f2", "type": "textarea", "label": "What a friend would say"}, {"id": "f3", "type": "textarea", "label": "A kinder or neutral statement"}, {"id": "f4", "type": "textarea", "label": "How I feel after saying it"}]'::jsonb, array['body image', 'self-talk', 'thinking traps']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('my-body-thank-you-cards-craft', 'My Body Thank-You Cards Craft', 'kids'::resource_kind, 'A craft where a child makes thank-you cards to their body for what it does.', 'Use it to help a child appreciate their body for what it does.', array['Children']::text[], '25 minutes', 'Give the child cards and crayons. They draw their legs, hands or heart and write a thank-you. The parent adds one for their own body. Keep talk on abilities and feelings, never looks.', '[{"id": "f0", "type": "textarea", "label": "Draw a part of my body"}, {"id": "f1", "type": "textarea", "label": "Thank you for..."}, {"id": "f2", "type": "textarea", "label": "Something I like to do"}, {"id": "f3", "type": "textarea", "label": "Who I can tell if I feel bad about myself"}]'::jsonb, array['body image', 'gratitude', 'art']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('media-messages-sorting-worksheet', 'Media Messages Sorting Worksheet', 'worksheet'::resource_kind, 'A worksheet for noticing media messages about how people look and choosing which to question.', 'Use it to help a client examine media messages about looks.', array['Teens', 'Adults']::text[], '25 minutes', 'Ask the client to list where they see messages about appearance and sort them into ones they want to believe and ones they want to question. Avoid details on numbers or measurements. Plan one change such as muting an account.', '[{"id": "f0", "type": "textarea", "label": "Where I see these messages"}, {"id": "f1", "type": "textarea", "label": "What they say"}, {"id": "f2", "type": "textarea", "label": "How they make me feel"}, {"id": "f3", "type": "textarea", "label": "Ones I want to question"}, {"id": "f4", "type": "textarea", "label": "One change I can make"}]'::jsonb, array['body image', 'media', 'boundaries']::text[], '2026-10-24T15:00:00+00:00'::timestamptz),
  ('compliments-beyond-looks-game', 'Compliments Beyond Looks Game', 'game'::resource_kind, 'A game where players give and receive compliments about character and actions, not appearance.', 'Use it to help a group practice noticing each other beyond looks.', array['Teens', 'Groups']::text[], '20 minutes', 'Set the rule: no compliments about looks. Players give one about a quality or action. The receiver says thanks. Debrief on how it felt and what they believe about their own qualities.', '[{"id": "f0", "type": "textarea", "label": "A compliment I gave"}, {"id": "f1", "type": "textarea", "label": "One I received"}, {"id": "f2", "type": "textarea", "label": "How it felt"}, {"id": "f3", "type": "textarea", "label": "A quality of mine I like"}]'::jsonb, array['body image', 'strengths', 'group']::text[], '2026-10-24T15:00:00+00:00'::timestamptz)
